  function prepare(command){
    draftText=command;
    const draft=root.querySelector('.draft');
    draft.hidden=false;
    draft.querySelector('textarea').value=command;
    say('Lời đã viết giúp người rồi, vẫn có thể sửa. Sau khi đưa vào khung nhập, do người quyết định khi nào gửi.');
    draft.scrollIntoView({block:'nearest'});
  }

  function appendDraft(){
    const command=root.querySelector('.draft textarea').value.trim();
    if(!command){say('Bản nháp trống.');return;}
    if(config.preview){
      say('Xác nhận biểu diễn hoàn tất, chưa gửi, chưa kết toán.\nBản nháp: '+command);
      return;
    }
    const area=hd.querySelector('#send_textarea');
    if(!area||!('value' in area)){
      say('Không tìm thấy khung nhập văn bản quán rượu, vui lòng sao chép thủ công bản nháp phía trên.');
      return;
    }
    const current=area.value;
    if(current.trim()&&!hw.confirm('Trong khung nhập đã có nội dung rồi. Bạn có muốn giữ lại nội dung cũ và nối câu này vào phía sau không?')){
      say('Đã hủy nối thêm, khung nhập văn bản gốc không thay đổi.');
      return;
    }
    try{
      area.value=current.trim()?current.replace(/\s+$/,'')+'\n'+command:command;
      area.dispatchEvent(new (area.ownerDocument.defaultView.Event)('input',{bubbles:true}));
      area.dispatchEvent(new (area.ownerDocument.defaultView.Event)('change',{bubbles:true}));
      closeMenu();
      area.focus();
    }catch(e){
      say('Nối thêm thất bại, vui lòng sao chép bản nháp thủ công.');
    }
  }

