    shape.placeholder='Ví dụ: hành trang, trang sức hộ thân; để trống thì tùy theo tổ hợp tứ tượng Định Cắt Gọt';
    shape.setAttribute('aria-label','Hình thái hoặc phương hướng khí vật');
    left.appendChild(shape);

    const summary=node('div','summary');
    left.appendChild(summary);

    const consentLabel=node('label','confirm');
    const consent=node('input');
    consent.type='checkbox';
    consentLabel.append(
      consent,
      node('span','','Ta đã đối chiếu các thanh giản đã chọn: 2 giản cần 2000 FP, 3 giản cần 3000 FP; thực tế thực hiện sẽ tiêu hao thanh giản đã chọn. Nơi này chỉ tạo bản nháp.')
    );
    left.appendChild(consentLabel);

    const prepareButton=button('Dùng những thẻ này, Thúy Ngọc Tài Cảnh',async()=>{
      if(busy)return;
      busy=true;
      prepareButton.disabled=true;
      const previousSignature=data.signature;
      const previousSelection=Array.from(selected);
      try{
        const latest=await getSnapshot();
        if(!dialog||page!=='jade')return;
        if(!latest.ok){
          say('Tái kiểm tra thất bại: '+latest.reason+'。Chưa tạo chỉ thị tài cảnh.');
          return;
        }
        if(latest.signature!==previousSignature){
          data=latest;
          selected=new Set(previousSelection.filter(k=>latest.jades.some(j=>j.key===k)));
          updateBadges();
          showPage('jade',false);
          say('Túi đồ hoặc FP đã thay đổi. Đã cập nhật dữ liệu, vui lòng đối chiếu và xác nhận lại.');
          return;
        }

        const chosen=data.jades.filter(j=>selected.has(j.key));
        if(chosen.length<2||chosen.length>3||!consent.checked){
          say('Vui lòng chọn 2～3 thẻ, và tích chọn xác nhận chi phí cùng nguyên liệu.');
          return;
        }
        const cost=chosen.length===2?2000:3000;
        if(data.fp!==null&&data.fp<cost){
          say('FP đã đọc không đủ. Chưa tạo chỉ thị tài cảnh.');
          return;
        }

        let command='Thiên Hào, ta chọn xong rồi! Hãy dùng '+chosen.map(j=>j.key).join('、')+' để Thúy Ngọc Tài Cảnh nhé.';
        if(shape.value.trim())command+='Ta muốn làm nó thành thế này: '+shape.value.trim()+'。';
        command+='Lần này '+cost+' FP và các ngọc giản đã chọn ta đều xác nhận rồi, nếu đủ thì bắt đầu đi!';

        /*
         * Cốt lõi khớp theo tên viết tắt địa điểm / tên key đầy đủ.
         * Tránh địa danh ngắn, phương hướng nhập vào hoặc từ phủ định ngoài ý muốn thay đổi ý đồ vòng này.
         */
        const matched=data.jades.filter(j=>
          command.includes(j.key)||(j.name&&command.includes(j.name))
        ).map(j=>j.key);
        const exact=matched.length===chosen.length&&matched.every(k=>selected.has(k));
        if(!exact){
          say('Phát hiện tên viết tắt địa danh chồng chéo hoặc văn bản phương hướng khớp thêm thanh giản khác. Để tránh cốt lõi chọn nhầm, vui lòng sửa phương hướng, hoặc sửa khớp chọn giản chính xác của cốt lõi trước.');
          return;
        }
        if(/不要|不用|不想|不必|别|先不|暂时不|等等再|取消|算了|作罢|不可以|不同意|不行|拒绝|下次再/.test(command)){
          say('Địa danh hoặc phương hướng chứa từ kích hoạt phủ định của cốt lõi, có thể khiến chỉ thị bị hủy. Vui lòng điều chỉnh phương hướng hoặc kiểm tra lại phán định ý đồ của cốt lõi.');
          return;
        }

        prepare(command);
      }finally{
        busy=false;
        if(prepareButton.isConnected)update();
      }
    },'primary');
    left.appendChild(prepareButton);

    function update(){
      const count=selected.size;
      const cost=count===2?2000:count===3?3000:null;
      summary.textContent='Đã chọn '+count+' thẻ · '+
        (cost===null?'Cần chọn 2～3 thẻ':cost+' FP')+
        '\nSố dư hiện tại: '+(data.fp===null?'Chưa đọc, gửi xong phải do cốt lõi kiểm tra':data.fp+' FP')+
        (data.jades.length>6?'\nCảnh báo: Số lượng thanh giản trong lưu trữ vượt quá giới hạn tối đa 6 thẻ của cốt lõi.':'');
      prepareButton.disabled=
        busy||!data.ok||count<2||count>3||!consent.checked||
        (cost!==null&&data.fp!==null&&data.fp<cost);
    }
    consent.addEventListener('change',update);
    shape.addEventListener('input',()=>{
      const oldDraft=root.querySelector('.draft');
      if(oldDraft)oldDraft.hidden=true;
    });
    update();

    right.appendChild(node('p','quote','「Sơn hà nào phải mây khói thoảng qua, cố nhân cũng chẳng chỉ dừng lại ở hôm qua.」'));
    const legend=node('div','legend');
    [
      ['Sơn Cốt','Phòng hộ kiên cường · Gánh vác định thần'],
      ['Thủy Mạch','Cơ động lưu chuyển · Thu nạp thoát thân'],
      ['Phong Tín','Cảm tri cảnh báo · Nhanh nhạy tin tức'],
      ['Nhân Yên','Che chở hồi phục · Xã giao thông hành']
    ].forEach(([a,b])=>{
      const box=node('div');
      box.append(node('strong','',a),node('small','',b));
      legend.appendChild(box);
    });
    right.appendChild(legend);

  }

