  function openMenu(trigger){
    if(store.active){
      const same=store.active===dialog;
      if(same){requestMenuClose(store.active);return;}
      store.active.close();
    }
    triggerButton=trigger;
    host=hd.createElement('div');
    host.setAttribute('data-qy19-menu-host','');
    root=host.attachShadow({mode:'open'});
    const style=hd.createElement('style');
    style.textContent=qyOptMenuCSS();
    dialog=node('dialog');
    dialog.setAttribute('aria-label','Thiên Hào Vân Các Thiên Cơ Sách');

    const head=node('header','head'),copy=node('div');
    copy.append(
      node('h1','title','Vân Các Thiên Cơ Sách'),
      node('p','subtitle','Thiên Hào · Nhặt nhạnh phong vật nhân gian, vấn hỏi muôn vàn mệnh đồ')
    );
    const actions=node('div','head-actions');
    const toggle=button('',()=>{
      const saved=store.set('theme',theme()==='night'?'day':'night');
      say(saved?'Phối màu ngày đêm đã chuyển đổi và lưu lại.':'Phối màu ngày đêm đã chuyển đổi; môi trường hiện tại không cho phép lưu trữ lâu dài.');
    });
    toggle.dataset.themeToggle='';
    const close=button('×',closeMenu,'close');
    close.setAttribute('aria-label','Đóng menu');
    actions.append(toggle,close);
    head.append(copy,actions);

    const toolbar=node('div','toolbar'),badges=node('div','badges');
    toolbar.append(badges,button('↻ Làm Mới Hành Nang',refreshData));
    const source=node('div','source note');
    const body=node('div','body');
    const foot=node('footer','foot');
    foot.append(source,node('div','','Menu chỉ đọc lưu trữ, chuẩn bị chỉ thị; sẽ không tự tiêu hao FP hoặc nguyên liệu.'));

    dialog.setAttribute('data-qy192-book','');
    const spine=node('aside','book-spine');
    spine.setAttribute('aria-hidden','true');
    spine.appendChild(node('span','','Thiên Hào Vân Sách'));
    const bookTabs=node('nav','book-tabs');
    bookTabs.setAttribute('aria-label','Mục lục Thiên Cơ Sách');
    [['home','Tổng quan'],['oracle','Thiên Cơ'],['jade','Thập Ngọc'],['service','Linh Ngữ'],['settings','Điều Luật']].forEach(([key,label])=>{
      const tab=button(label,()=>showPage(key));
      tab.dataset.bookPage=key;
      bookTabs.appendChild(tab);
    });
    dialog.append(head,toolbar,spine,body,bookTabs,foot);

    dialog.setAttribute('data-qy193-cloud','');

    dialog.setAttribute('data-qy194','');

