  function record(v){
    return v!==null&&typeof v==='object'&&!Array.isArray(v);
  }
  function text(v){
    if(typeof v==='string'||typeof v==='number')return String(v);
    return '';
  }
  function number(v){
    if(typeof v==='number')return Number.isFinite(v)&&v>=0?v:null;
    if(typeof v==='string'&&/^\d+(?:\.\d+)?$/.test(v.trim()))return Number(v);
    return null;
  }

  async function getSnapshot(){
    let vars;
    try{
      if(config.preview){
        vars=demoVariables();
      }else{
        let reader;
        if(typeof getVariables==='function'){
          reader=opts=>getVariables(opts);
        }else if(typeof w.getVariables==='function'){
          reader=opts=>w.getVariables(opts);
        }else if(typeof hw.getVariables==='function'){
          reader=opts=>hw.getVariables(opts);
        }
        if(!reader)throw new Error('Môi trường hiện tại không cung cấp getVariables');
        vars=await reader({type:'message',message_id:'latest'});
      }

      const actor=vars&&vars.stat_data&&vars.stat_data.主角;
      if(!record(actor))throw new Error('Không tìm thấy stat_data.主角');
      if(!record(actor.背包))throw new Error('Không tìm thấy đối tượng ba lô hợp lệ của nhân vật chính');

      let fp=null;
      for(const key of ['FP','fp','命运点数','命运点数(FP)']){
        const value=number(actor[key]);
        if(value!==null){fp=value;break;}
      if(fp===null&&record(vars.stat_data)){for(const key of ['命运点数','FP','fp','命运点数(FP)']){const value=number(vars.stat_data[key]);if(value!==null){fp=value;break;}}}
      }

