function qy233ReadJades(bag){
 const nameFields=[
  '名称','名字','物品名','物品名称','物品名字',
  '显示名称','显示名','道具名称','道具名',
  'name','Name','itemName','item_name',
  'displayName','display_name','title'
 ];

 const detailFields=[
  '效果','属性','数据','详情',
  'effect','effects','attributes','data'
 ];

 const aliases={
  type:['象','四象','象类','类型','type','element'],
  scene:['景','风景','景色','场景','scene','scenery'],
  trace:['拓痕','故人','人物','羁绊','trace','imprint']
 };

 function valueText(value){
  if(typeof value==='string')return value.trim();
  if(typeof value==='number'&&Number.isFinite(value)){
   return String(value);
  }
  return '';
 }

 function readField(object,field){
  if(!record(object))return '';
  if(!Object.prototype.hasOwnProperty.call(object,field))return '';
  return valueText(object[field]);
 }

 function readDetail(item,kind){
  const sources=[];

  if(record(item)){
   for(const field of detailFields){
    if(Object.prototype.hasOwnProperty.call(item,field)&&
       record(item[field])){
     sources.push(item[field]);
    }
   }
   sources.push(item);
  }

  for(const source of sources){
   for(const field of aliases[kind]){
    const value=readField(source,field);
    if(value)return value;
   }
  }

  return 'Chưa ghi chú';
 }

 const result=[];

 for(const key of Object.keys(bag)){
  const item=bag[key];
  const candidates=[];

  // Trường tên rõ ràng được ưu tiên hiển thị.
  if(record(item)){
   for(const field of nameFields){
    const value=readField(item,field);
    if(value)candidates.push(value);
   }
  }

  // Khóa túi đồ luôn tham gia nhận diện.
  candidates.push(key);

  const matchedName=candidates.find(name=>name.includes('青玉简'));
  if(!matchedName)continue;

  /*
   * Chỉ giữ lại hiển thị "tên địa điểm viết tắt" ban đầu cho định dạng chuẩn cũ.
   * Định dạng mới giữ lại tên đầy đủ, tránh cắt gọt sai và mở rộng phạm vi khớp tên viết tắt.
   */
  const legacy=/^\[青玉简:([^\]]+)\]$/.exec(matchedName);
  const displayName=legacy?legacy[1]:matchedName;

  result.push({
   key, // Khóa lưu trữ gốc, không đổi tên, không ghi đè.
   name:displayName,
   type:readDetail(item,'type'),
   scene:readDetail(item,'scene'),
   trace:readDetail(item,'trace')
  });
 }

 return result;
}
const jades=qy233ReadJades(actor.背包);
/* qy_jade_v233_end */

      const effects=record(actor.状态效果)?actor.状态效果:{};
      const oracles=Object.keys(effects)
