          key,
          time:record(effects[key])?text(effects[key].剩余时间):'',
          effect:record(effects[key])?text(effects[key].效果):text(effects[key])
        }));

      return {
        ok:true,fp,jades,oracles,
        signature:JSON.stringify({fp,jades}),
        reason:config.preview?'Dữ liệu biểu diễn, không thuộc bản lưu thực tế':'Đã đọc biến tin nhắn mới nhất'
