  function closeMenu(){
    if(dialog)requestMenuClose(dialog);
  }

  function requestMenuClose(target){
    if(!target||!target.open||target.dataset.closing)return;
    const reduced=hw.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if(store.state.motion==='off'||reduced){
      target.close();
      return;
    }
    target.dataset.closing='1';
    let completed=false;
    let timer;
    const finish=()=>{
      if(completed)return;
      completed=true;
      hw.clearTimeout(timer);
      target.removeEventListener('animationend',ended);
      if(target.open)target.close();
    };
    const ended=event=>{
      if(event.target===target&&event.animationName==='q194-close')finish();
    };
    target.addEventListener('animationend',ended);
    timer=hw.setTimeout(finish,240);
  }

