<div data-opd-root="$1"></div>
<textarea id="opd-raw" style="display:none">$2</textarea>
<script>
/* ================= 面板配置 ================= */
    const PANELS = {
        business_info: { title: '项目台账',          theme: 'biz' },
        ledger_info: { title: '收支账簿',          theme: 'led' },
        archive_info: { title: '世界书归档',        theme: 'arc' },
    };

    /* ================= 字段渲染规则 ================= */
    const BADGE_KEYS = ['品质', '状态'];
    const PROG_KEYS  = ['进度', '已激活', '阶段'];
    const NUM_KEYS   = ['金额', '预算', '已投入', '剩余', '收入合计', '支出合计', '净利',
                        '累计收入', '累计支出', '累计净利', '武器攻击', '经验', '剩余追忆', '目标'];
    const FOLD_KEYS  = ['效果', '备注', '异象', '风险', '共鸣结果', '说明', '摘要', '描述', '结果'];
    const CODE_KEYS  = ['comment', 'content', 'key'];
    const PLAIN_SEC  = ['备注', '摘要', '说明'];

    /* ================= 工具 ================= */
    /* ⚠️⚠️ 铁律：本文件里**绝不允许出现「预编码的 HTML 实体」**（形如 与号 + amp + 分号 那种）。
     * 工坊范式的文档要经过「showdown 转义 → 酒馆助手取出 → iframe 解析」多层 HTML 处理，
     * 字面实体会被多解一层：amp 实体解成裸与号、数字 39 实体解成裸单引号 ——
     * 一旦解出裸引号，整段 JS 就是 SyntaxError，面板直接空白（本机实测踩过）。
     * 所以必须用下面这种「运行时拼出来」的写法。 */
    const AMP = '\u0026';
    const ESC_MAP = { '&': AMP + 'amp;', '<': AMP + 'lt;', '>': AMP + 'gt;', '"': AMP + 'quot;', "'": AMP + '#39;' };
    function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, c => ESC_MAP[c]); }

    function clamp01(x) { return x < 0 ? 0 : (x > 1 ? 1 : x); }

    /** 解析 "3/7" "2/3 开启" → {cur,max,tail}；失败返回 null */
    function parseRatio(v) {
        const m = String(v).match(/(\d+)\s*\/\s*(\d+)\s*(.*)$/);
        if (!m) return null;
        const cur = Number(m[1]), max = Number(m[2]);
        if (!isFinite(cur) || !isFinite(max) || max <= 0) return null;
        return { cur, max, tail: (m[3] || '').trim() };
    }

    /* ================= 富文本内联处理 =================
     * 输入必须是**已转义**的文本；因此原文里的 "->" 在已转义文本中会呈现为
     * 「减号 + 转义后的大于号」的形式，两种都要认。 */
    function resBar(kind, cur, max) {
        const c = Number(cur), m = Number(max);
        if (!isFinite(c) || !isFinite(m) || m <= 0) return `HP ${esc(cur)}/${esc(max)}`;
        const pct = Math.round(clamp01(c / m) * 100);
        const low = (c / m) <= 0.3;   // ← 数值条件判断：低于 30% 告警
        return `<span class="opd-res${low ? ' low' : ''}" data-kind="${kind}">`
             + `<span class="opd-bar"><i style="width:${pct}%"></i></span>`
             + `<em>${c}/${m}</em></span>`;
    }

    function inline(s) {
        let t = String(s);
        // 资源条
        t = t.replace(/HP\s*\[?(\d+)\s*\/\s*(\d+)\]?/g, (m, c, x) => resBar('hp', c, x));
        t = t.replace(/MP\s*\[?(\d+)\s*\/\s*(\d+)\]?/g, (m, c, x) => resBar('mp', c, x));
        t = t.replace(/SP\s*\[?(\d+)\s*\/\s*(\d+)\]?/g, (m, c, x) => resBar('sp', c, x));
        // 五维属性 力[10]
        t = t.replace(/([力敏体智精])\s*\[(\d+)\]/g,
            (m, c, n) => `<span class="opd-attr" data-c="${c}">${n}</span>`);
        // 箭头：原文的 "->" 经过转义会呈现为「减号 + 转义大于号」，两种都要认（用 \u0026 避开字面实体）
        // ⚠️ 一律用「函数形式」而不是美元数字模板串：工坊版会把本脚本嵌进 replaceString，
        //    而 ST 会替换**所有**美元数字 —— 用它会被替换成捕获组内容而语法崩溃。
        //    所以本文件里任何地方都不允许出现 美元符号紧跟数字（连注释也不行）。
        t = t.replace(/-\u0026gt;|\u2192|\u2014\u2014\u0026gt;/g, () => '<span class="opd-arrow">\u2192</span>');
        t = t.replace(/(^|[^\u0026])->/g, (m, p1) => p1 + '<span class="opd-arrow">\u2192</span>');
        t = t.replace(/EXP\s*\+?(\d+)/g, (m, n) => 'EXP <span class="opd-num">+' + n + '</span>');
        // 数值负数着色
        t = t.replace(/(^|\s)(-\d+)/g, (m, p1, p2) => p1 + '<span class="opd-num opd-neg">' + p2 + '</span>');
        return t;
    }

    /* ================= 解析 ================= */
    function splitCells(line) {
        let s = String(line).trim();
        if (s.charAt(0) === '|') s = s.slice(1);
        if (s.charAt(s.length - 1) === '|') s = s.slice(0, -1);
        return s.split('|').map(c => c.trim()).filter(Boolean).map(cell => {
            const i = cell.search(/[:：]/);
            if (i < 0) return { k: '', v: cell };
            return { k: cell.slice(0, i).trim(), v: cell.slice(i + 1).trim() };
        });
    }

    /** 原始文本 → [{title, rows:[[{k,v}]]}] */
    function parseBlocks(text) {
        const clean = String(text || '').replace(/<\/?[a-z_]*_info>/gi, '');
        const sections = [];
        let cur = null;
        const open = (t) => { cur = { title: t, rows: [] }; sections.push(cur); };
        for (const raw of clean.split(/\r?\n/)) {
            const line = raw.trim();
            if (!line) continue;
            const mSec = line.match(/^\{(.+?)\}$/);
