                            '档位': it['档位'] || it['品质'] || '铜',
                            '时间': it['时间'] || eff['达成时间'] || '',
                            '经过': it['经过'] || eff['达成经过'] || ''
                        };
                    }
                });
                clearTimeout(timer);
                done(a);
            } catch (e) { clearTimeout(timer); done(null); }
        }, function () { clearTimeout(timer); done(null); });
    }

    /* ---------- 渲染 ---------- */
    function badgeHtml(name, meta, isNew) {
        var cat = CATS.indexOf(meta['类别']) >= 0 ? meta['类别'] : '战斗';
        var tr = tierOf(meta);
        var tip = name + (meta['时间'] ? ' · ' + meta['时间'] : '') + '｜' + (meta['描述'] || '');
        return '<span class="ach-badge' + (isNew ? ' is-new' : '') + '" data-cat="' + esc(cat) + '" title="' + esc(tip) + '">'
            + '<span class="dot"></span><span class="nm">' + esc(name) + '</span>'
            + '<span class="tr">' + esc(tr) + '</span></span>';
    }

    function wallHtml(ach, highlight) {
        var keys = Object.keys(ach || {});
        var h = '<div class="ach-wallhead"><span>荣誉殿堂 · 成就墙</span>'
            + '<em>' + (keys.length ? '已收录 ' + keys.length + ' 枚' : '尚无收录') + '</em></div>';
        if (!keys.length) {
            h += '<div class="ach-empty">殿堂的墙上还空着。去冒险吧——最帅的那些瞬间，往往连你自己都没意识到。</div>';
            return h;
        }
        /* 按档位降序、同类相邻 */
        keys.sort(function (a, b) {
            var d = tierRank(ach[b]) - tierRank(ach[a]);
            return d || a.localeCompare(b, 'zh');
        });
        h += '<div class="ach-grid">';
        keys.forEach(function (k) {
            h += badgeHtml(k, ach[k] || {}, k === highlight);
        });
        h += '</div>';
        /* 类别统计 */
        var stat = {};
        keys.forEach(function (k) {
            var c = (ach[k] || {})['类别'];
            if (CATS.indexOf(c) >= 0) stat[c] = (stat[c] || 0) + 1;
        });
        if (Object.keys(stat).length) {
            h += '<div class="ach-stats">';
            CATS.forEach(function (c) {
                if (stat[c]) h += '<span class="ach-stat" data-cat="' + esc(c) + '"><span class="dot"></span>' + esc(c) + ' × ' + stat[c] + '</span>';
            });
            h += '</div>';
        }
        return h;
    }

    function render(raw, ach) {
        var f = parseFields(raw);
        var isWallOnly = f['模式'] === '成就墙';
        var html = '<div class="ach-hall" data-ach-root="1">'
            + '<div class="ach-head"><span class="ach-glyph">✦</span><span class="ach-title">成就 · 荣誉殿堂</span>'
            + '<span class="ach-count"></span><span class="ach-chev">▼</span></div>'
            + '<div class="ach-body">';
        var highlight = '';
        if (!isWallOnly && f['名称']) {
            var cat = CATS.indexOf(f['类别']) >= 0 ? f['类别'] : '战斗';
            var tr = TIERS[f['档位']] ? f['档位'] : '铜';
            highlight = f['名称'];
            html += '<div class="ach-unlock" data-tier="' + esc(tr) + '">'
                + '<span class="ach-medal">' + esc(tr === '金' ? '金' : tr === '银' ? '银' : '铜') + '</span>'
                + '<span class="ach-main">'
                + '<span class="ach-tag" data-cat="' + esc(cat) + '">' + esc(cat) + ' · ' + esc(tr) + '档</span>'
                + '<div class="ach-name">成就解锁<small>' + esc(f['名称']) + '</small></div>'
                + '<div class="ach-desc">' + esc(f['描述'] || '') + '</div>'
                + ((f['时间'] || f['经过']) ? '<div class="ach-when">'
                    + (f['时间'] ? '🕒 ' + esc(f['时间']) : '') + (f['经过'] ? ' · ' + esc(f['经过']) : '')
                    + '</div>' : '')
                + '</span></div>';
        }
        if (ach && Object.keys(ach).length) {
            html += wallHtml(ach, highlight);
        } else if (isWallOnly || !f['名称']) {
            html += '<div class="ach-empty">成就墙需在酒馆内读取变量。当前环境拿不到 MVU 数据'
                 + (ach === null ? '——先在酒馆里跑起来吧。' : '——殿堂的墙上还空着。') + '</div>';
        }
        html += '</div></div>';
        return html;
    }

    /* ---------- 入口 ---------- */
    var root = document.querySelector('[data-ach-app]');
    var rawEl = document.getElementById('ach-raw');
    var raw = rawEl ? rawEl.value : '';
    var f = parseFields(raw);
    var isWall = f['模式'] === '成就墙';

    root.innerHTML = render(raw, isWall ? {} : null);   // 先渲染（墙数据后补）

    readAchievements(function (ach) {
        var el = root.querySelector('[data-ach-root]');
        if (!el) return;
        var keep = el.closest('.ach-hall').classList.contains('collapsed');
        root.innerHTML = render(raw, ach);
        if (keep) root.querySelector('.ach-hall').classList.add('collapsed');
        bind(root);
    });

    function bind(r) {
        r.querySelectorAll('.ach-head').forEach(function (h) {
            h.addEventListener('click', function () {
                var p = h.closest('.ach-hall');
                if (p) p.classList.toggle('collapsed');
            });
        });
        var cnt = r.querySelector('.ach-count');
        var wall = r.querySelectorAll('.ach-badge').length;
        if (cnt && wall) cnt.textContent = wall + ' 枚';
    }
    bind(root);

    var r0 = document.getElementById('ach-raw');
    if (r0 && r0.parentNode) r0.parentNode.removeChild(r0);
})();

</script>
</body>
</html>
