        }

        .reward-pill-container {
            display: flex;
            flex-wrap: wrap;
            gap: 8px;
            align-items: center
        }

        .reward-pill {
            position: relative;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            padding: 6px 14px;
            border-radius: 12px 3px;
            cursor: pointer;
            user-select: none;
            transition: all .3s cubic-bezier(.2, .8, .25, 1);
            background: #18031ce6;
            border: 1.5px solid rgba(255, 64, 129, .45);
            box-shadow: 0 0 12px #ba186b59;
            overflow: hidden;
            min-height: 32px
        }

        .reward-pill:hover {
            border-color: #ff69b4d9;
            box-shadow: 0 0 18px #ff14938c;
            transform: translateY(-1px)
        }

        .reward-text {
            color: #ffcc80;
            font-weight: 700;
            font-size: 13px;
            letter-spacing: .5px;
            text-shadow: 0 0 8px rgba(255, 152, 0, .7);
            transition: filter .3s ease, opacity .3s ease;
            white-space: nowrap
        }

        .reward-succubus-seal {
            position: absolute;
            inset: 0;
            border-radius: 10px 2px;
            background: linear-gradient(135deg, #6b21a8, #c026d3 45%, #e11d48);
            background-size: 200% 200%;
            animation: succubusSealShimmer 3.2s infinite ease-in-out;
            border: 1px solid rgba(255, 182, 193, .85);
            box-shadow: 0 0 14px #ec4899bf, inset 0 0 8px #ffffff59;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 4px;
            padding: 0 8px;
            pointer-events: none;
            z-index: 2;
            transition: transform .25s ease, opacity .25s ease
        }

        @keyframes succubusSealShimmer {
            0% {
                background-position: 0% 50%;
                filter: brightness(1)
            }

            50% {
                background-position: 100% 50%;
                filter: brightness(1.22) drop-shadow(0 0 10px #ff007f)
            }

            to {
                background-position: 0% 50%;
                filter: brightness(1)
            }
        }

        .seal-heart {
            font-size: 16px;
            line-height: 1;
            color: #fff;
            filter: drop-shadow(0 0 7px #ff0055) drop-shadow(0 0 12px #ff1493);
            animation: sealHeartBeat 1.35s infinite ease-in-out;
            display: inline-block;
            user-select: none
        }

        @keyframes sealHeartBeat {

            0%,
            100% {
                transform: translate3d(0, 0, 0) scale(1) rotate(0)
            }

            20% {
                transform: translate3d(0, 0, 0) scale(1.1) rotate(-4deg)
            }

            35% {
                transform: translate3d(0, 0, 0) scale(1.05) rotate(3deg)
            }

            55% {
                transform: translate3d(0, 0, 0) scale(1.38) rotate(-6deg)
            }

            70% {
                transform: translate3d(0, 0, 0) scale(1.2) rotate(2deg)
            }

            85% {
                transform: translate3d(0, 0, 0) scale(1.04) rotate(-1deg)
            }
        }

        .seal-crack-mesh {
            position: absolute;
            inset: 0;
            pointer-events: none;
            opacity: 0;
            transition: opacity .15s ease;
            overflow: hidden
        }

        .crack-svg {
            width: 100%;
            height: 100%;
            filter: drop-shadow(0 0 3px #ffffff) drop-shadow(0 0 7px #ff007f)
        }

        .reward-pill.cracking {
            animation: sealCrackShiver .45s cubic-bezier(.36, .07, .19, .97) both !important
        }

        .reward-pill.cracking .reward-succubus-seal {
            box-shadow: 0 0 20px #fff, 0 0 35px #ff007f, inset 0 0 15px #fff !important;
            filter: brightness(1.6) !important
        }

        .reward-pill.cracking .seal-crack-mesh {
            opacity: 1 !important;
            animation: crackFlash .45s ease-in-out forwards
        }

        @keyframes crackFlash {
            0% {
                opacity: .3;
                transform: scale(.95)
            }

            50% {
                opacity: 1;
                transform: scale(1.02);
                filter: drop-shadow(0 0 6px #ffffff) drop-shadow(0 0 12px #ff0055)
            }

            to {
                opacity: 1;
                transform: scale(1.06);
                filter: drop-shadow(0 0 10px #ffffff) brightness(2.2)
            }
        }

        @keyframes sealCrackShiver {
            0% {
                transform: translate(0) rotate(0)
            }

            15% {
                transform: translate(-2px, 1.5px) rotate(-1deg)
            }

            30% {
                transform: translate(2px, -1.5px) rotate(1.5deg)
            }

            45% {
                transform: translate(-3px, -1px) rotate(-1.5deg)
            }

            60% {
                transform: translate(3px, 1.5px) rotate(1.5deg)
            }

            75% {
                transform: translate(-2px, 2px) rotate(-1deg)
            }

            90% {
                transform: translate(2px, -2px) rotate(.8deg)
            }

            to {
                transform: translate(0) rotate(0)
            }
        }

        .reward-pill.masked .reward-text {
            filter: blur(4px);
            opacity: .15;
            user-select: none
        }

        .reward-pill.revealed .reward-succubus-seal {
            display: none
        }

        .reward-pill.revealed .reward-text {
            filter: none;
            opacity: 1;
            color: #ffe082;
            text-shadow: 0 0 10px rgba(255, 152, 0, .9), 0 0 18px rgba(255, 20, 147, .7);
            animation: rewardTextRevealGlow .65s cubic-bezier(.2, .8, .25, 1)
        }

        @keyframes rewardTextRevealGlow {
            0% {
                transform: scale(.85);
                opacity: 0;
                filter: brightness(2.2) drop-shadow(0 0 15px #ffffff)
            }

            50% {
                transform: scale(1.08);
                opacity: 1;
                filter: brightness(1.6) drop-shadow(0 0 12px #ff9800)
            }

            to {
                transform: scale(1);
                filter: none
            }
        }

        .reward-burst-heart {
            position: fixed;
            pointer-events: none;
            z-index: 99999;
            user-select: none;
            line-height: 1;
            transform: translate(-50%, -50%);
            will-change: transform, opacity;
            animation: rewardHeartFly .85s cubic-bezier(.12, .85, .3, 1) forwards
        }

        @keyframes rewardHeartFly {
            0% {
                transform: translate(-50%, -50%) scale(.3) rotate(0);
                opacity: 0;
                filter: drop-shadow(0 0 4px #ff007f)
            }

            20% {
                opacity: 1;
                transform: translate(calc(-50% + var(--vx) * .4), calc(-50% + var(--vy) * .4)) scale(1.35) rotate(calc(var(--rot) * .4));
                filter: drop-shadow(0 0 10px #ff0055) brightness(1.4)
            }

            70% {
                opacity: .9;
                transform: translate(calc(-50% + var(--vx) * .85), calc(-50% + var(--vy) * .85 + 5px)) scale(1.05) rotate(calc(var(--rot) * .85))
            }

            to {
                opacity: 0;
                transform: translate(calc(-50% + var(--vx)), calc(-50% + var(--vy) + 12px)) scale(.3) rotate(var(--rot));
                filter: blur(2px)
            }
        }

        .board-blur-fade {
            transition: opacity .35s ease, transform .35s cubic-bezier(.16, 1, .3, 1) !important;
            filter: none !important;
            opacity: 0 !important;
            transform: scale(.96) translateZ(0) !important;
            pointer-events: none !important
        }

        .board-aphorism-banner {
