        }

        .aphorism-wing-right {
            background: linear-gradient(90deg, #ff80ab 0%, rgba(255, 64, 129, .45) 20%, transparent 100%)
        }

        .aphorism-heart-crest {
            color: #ff2a7a;
            font-size: 11px;
            letter-spacing: 2px;
            text-shadow: 0 0 8px #ff007f;
