        }

        .aphorism-title {
            font-size: 11px;
            color: #ff80ab;
            letter-spacing: 1.2px;
            font-style: italic;
            margin-bottom: 5px;
            opacity: .9;
            text-shadow: 0 0 6px rgba(255, 20, 147, .6)
        }

        .aphorism-text {
            font-family: ZCOOL KuaiLe, cursive, sans-serif;
            font-size: 14.5px;
            color: #ffc2d8;
            letter-spacing: 1.5px;
            text-shadow: 0 0 8px #ff007f, 0 0 16px rgba(255, 20, 147, .65);
            animation: aphorismGlow 3s infinite alternate ease-in-out;
            will-change: transform, opacity;
            filter: drop-shadow(0 0 6px #ff007f)
        }

        .aphorism-ornament-bottom {
            width: 40%;
            max-width: 140px;
            height: 1px;
            margin: 6px auto 0;
            background: linear-gradient(90deg, transparent 0%, rgba(255, 64, 129, .4) 50%, transparent 100%)
        }

        @keyframes aphorismGlow {

            0%,
            100% {
                opacity: .82;
                transform: scale(1)
            }

            50% {
                opacity: 1;
                transform: scale(1.02)
            }
        }

        .massive-hearts-stage {
            position: absolute;
            inset: 0;
            pointer-events: none;
            z-index: 4;
            overflow: hidden;
            opacity: 0;
            transition: opacity .8s ease
        }

        .stage-active-1 .massive-hearts-stage,
        .stage-active-2 .massive-hearts-stage,
        .stage-active-3 .massive-hearts-stage {
            opacity: 1
        }

        .chaos-heart {
            position: absolute;
            bottom: -30px;
            color: #ff1493;
            font-size: 20px;
            filter: drop-shadow(0 0 10px #ff007f);
            animation: chaosHeartRise 4s infinite linear
        }

        @keyframes chaosHeartRise {
            0% {
                transform: translateY(0) scale(.4) rotate(0);
                opacity: 0
            }

            20% {
                opacity: .9
            }

            80% {
                opacity: .8
            }

