            border-radius: 0 0 12px 12px;
            box-shadow: 0 0 12px #ff007f, inset 0 -2px 6px #fff;
            filter: drop-shadow(0 0 8px rgba(255, 0, 128, .8));
            animation: slimeOozeDown 6s infinite ease-in;
            transform-origin: top center;
            height: 180px;
            will-change: transform, opacity
        }

        @keyframes slimeOozeDown {
            0% {
                transform: scaleY(0) scaleX(1);
                opacity: 0
            }

            25% {
                transform: scaleY(.2) scaleX(1.1);
                opacity: .95
            }

            60% {
                transform: scaleY(.55) scaleX(.85);
                opacity: .9
            }

            85% {
                transform: scaleY(.8) scaleX(.95);
                opacity: .85
            }

            100% {
                transform: scaleY(1) translateY(40px) scaleX(.5);
                opacity: 0
            }
