            transition: opacity .8s ease
        }

        .stage-active-3 .crest-juice-fountain {
            opacity: 1
        }

        .fountain-top {
            top: 6px
        }

        .fountain-bottom {
            bottom: 6px;
            transform: translate(-50%) rotate(180deg)
        }

        .fountain-spray-drop {
            position: absolute;
            width: 6px;
            height: 8px;
            background: radial-gradient(circle at 35% 35%, #fff, #ff80ab 60%, #ff1493);
            border-radius: 50%;
            box-shadow: 0 0 8px #ff007f;
            animation: continuousSpurt 1.2s infinite ease-out
        }

        @keyframes continuousSpurt {
