                    </g>
                    <path class="crest-core-heart-glow"
                        d="M110,35C103,26 92,20 92,10C92,2 102,0 110,7C118,0 128,2 128,10C128,20 117,26 110,35Z"
                        fill="none" stroke="#ff80ab" stroke-width="1.2" opacity="0.9" />
                    <circle class="crest-core-light" id="crest-core-light-dot" cx="110" cy="12" r="2.8"
                        fill="#ffffff" />
                </g>
                <path d="M85,18Q72,5 60,12Q75,14 82,22Z" fill="#5a0044" stroke="#ff4081" stroke-width="1" />
                <path d="M135,18Q148,5 160,12Q145,14 138,22Z" fill="#5a0044" stroke="#ff4081" stroke-width="1" />
            </svg>
            <div class="top-crest-dropzone" id="top-crest-dropzone" title="Kéo trái tim độ hảo cảm 100% vào đây~"></div>
            <div class="eros-shop-banner" id="eros-shop-banner">
                <span class="shop-wing left">‹</span>
                <span class="shop-title-text"><span class="shop-word-aiyu">Ái Dục</span><span
                        class="shop-word-shangpu">Thương Tiệm</span></span>
                <span class="shop-wing right">›</span>
            </div>
        </div>
        <div class="crest-juice-fountain fountain-top stage-layer">
            <span class="fountain-spray-drop" style="--dx:-40px; --dy:-30px; animation-delay:0.1s;"></span>
            <span class="fountain-spray-drop"
                style="--dx:-18px; --dy:-45px; animation-delay:0.3s; width:8px; height:10px;"></span>
            <span class="fountain-spray-drop"
                style="--dx:0px;   --dy:-50px; animation-delay:0.0s; width:9px; height:12px;"></span>
            <span class="fountain-spray-drop" style="--dx:22px;  --dy:-42px; animation-delay:0.4s;"></span>
