        .hnt-empty { display: none; padding: 22px 10px; text-align: center; font-size: 0.82em; letter-spacing: 1px;
            color: rgba(232,220,192,0.55); background: rgba(0,0,0,0.16); border: 1px dashed rgba(232,220,192,0.22); border-radius: 4px; }

        /* ===== Nút chân trang ===== */
        .hnt-footer { display: flex; justify-content: center; flex-wrap: wrap; gap: 9px; margin-top: 14px; padding-top: 12px;
            border-top: 1px solid rgba(232,220,192,0.16); }
        .hnt-btn { padding: 9px 20px; font-family: inherit; font-size: 0.85em; letter-spacing: 1.5px; border: 1px solid transparent;
            border-radius: 4px; cursor: pointer; transition: all 0.2s; }
        .hnt-accept { color: #2b1d16; cursor: not-allowed; opacity: 0.45; border-color: #1b120c;
            background: linear-gradient(180deg, #8a7a5c 0%, #5d5140 100%); }
        .hnt-accept.hnt-ready { opacity: 1; cursor: pointer; border-color: #3e2a0c;
            background: linear-gradient(180deg, #f0d79a 0%, #d4a24c 56%, #a97c2e 100%); box-shadow: 0 3px 10px rgba(0,0,0,0.42); }
        .hnt-accept.hnt-ready:hover { filter: brightness(1.08); transform: translateY(-1px); }
        .hnt-refresh { color: #f0e3c4; border-color: rgba(232,220,192,0.35);
            background: linear-gradient(180deg, rgba(232,220,192,0.14) 0%, rgba(232,220,192,0.06) 100%); }
        .hnt-refresh:hover { color: #fff6e0; border-color: #d4a24c; background: rgba(212,162,76,0.18); }

        /* ===== Chọn nhiều: Đếm số lượng + Chọn tất cả ===== */
        .hnt-selinfo { flex: 1 1 100%; text-align: center; font-size: 0.74em; letter-spacing: 1px;
            color: rgba(232,220,192,0.55); }
        .hnt-selinfo.hnt-has { color: #d4a24c; font-weight: 700; }
        .hnt-selall { color: #f0e3c4; border-color: rgba(232,220,192,0.35);
            background: linear-gradient(180deg, rgba(232,220,192,0.14) 0%, rgba(232,220,192,0.06) 100%); }
        .hnt-selall:hover { color: #fff6e0; border-color: #d4a24c; background: rgba(212,162,76,0.18); }
        .hnt-card.hnt-selected::after { content: '✓'; position: absolute; z-index: 3; top: 7px; right: 9px;
            width: 19px; height: 19px; line-height: 19px; text-align: center; border-radius: 50%;
            font-size: 0.72em; font-weight: 700; color: #2b1d16;
            background: linear-gradient(180deg, #f0d79a 0%, #d4a24c 100%); border: 1px solid #3e2a0c; }

        @media (max-width: 430px) {
            .hnt-board { padding: 13px 10px 11px; }
            .hnt-title { letter-spacing: 3px; text-indent: 3px; }
            .hnt-frow { flex-direction: column; gap: 3px; }
            .hnt-flabel { flex: 0 0 auto; padding-top: 0; }
            .hnt-key { flex: 0 0 54px; }
            .hnt-btn { padding: 9px 14px; letter-spacing: 1px; }
        }
    </style>
</head>
<body>
    <div class="hnt-wrap">
        <div class="hnt-board">
            <div class="hnt-header">
                <h2 class="hnt-title">Bảng Treo Thưởng</h2>
                <div class="hnt-sub"><span class="hnt-swords">⚔</span> Hiệp Hội Thợ Săn · Thông Báo Ủy Thác · Thấy Thưởng Nhận Ngay <span class="hnt-swords">⚔</span></div>
            </div>

            <div class="hnt-controls">
                <div class="hnt-search-row">
                    <input type="text" class="hnt-search" placeholder="Tìm kiếm: Tiêu đề / Chi tiết / Khu vực / Nguyên liệu chỉ định" />
                    <button type="button" class="hnt-clear">Xóa bộ lọc</button>
                </div>
                <div class="hnt-frow"><span class="hnt-flabel">Độ nguy hiểm</span><div class="hnt-fgroup hnt-fgroup-star"></div></div>
                <div class="hnt-frow"><span class="hnt-flabel">Cấp bậc</span><div class="hnt-fgroup hnt-fgroup-level"></div></div>
                <div class="hnt-frow"><span class="hnt-flabel">Khu vực</span><div class="hnt-fgroup hnt-fgroup-region"></div></div>
            </div>

            <div class="hnt-list"></div>
            <div class="hnt-empty">Không có ủy thác phù hợp điều kiện</div>

            <div class="hnt-footer">
                <div class="hnt-selinfo">Chưa chọn ủy thác</div>
                <button type="button" class="hnt-btn hnt-accept" disabled>Tiếp nhận ủy thác</button>
                <button type="button" class="hnt-btn hnt-selall">Chọn tất cả đang hiện</button>
                <button type="button" class="hnt-btn hnt-refresh">Làm mới bảng treo thưởng</button>
            </div>
        </div>
    </div>

    <!-- Dữ liệu gốc được nhúng trực tiếp vào vùng ẩn để tránh nhầm lẫn khi phân tích cú pháp nhiều thẻ -->
    <div class="hnt-raw-data" style="display:none;">$1</div>

    <script>
        $(function () {
            var $root = $('body');
            var rawContent = $root.find('.hnt-raw-data').text() || '';

            var $list = $root.find('.hnt-list');
            var $empty = $root.find('.hnt-empty');
            var $search = $root.find('.hnt-search');
            var $accept = $root.find('.hnt-accept');
            var $refresh = $root.find('.hnt-refresh');
            var $selinfo = $root.find('.hnt-selinfo');
            var $selall = $root.find('.hnt-selall');

            var LEVELS = ['D', 'C', 'B', 'A', 'S'];
            var STAR_FILTERS = [['all', 'Tất cả'], ['1-2', '★1-2'], ['3-4', '★3-4'], ['5-6', '★5-6'], ['7+', '★7+']];
            var LEVEL_FILTERS = [['all', 'Tất cả'], ['D', 'D'], ['C', 'C'], ['B', 'B'], ['A', 'A'], ['S', 'S']];

            var state = { q: '', star: 'all', level: 'all', region: 'all' };
            var records = [];
            var selected = {};          /* Chọn nhiều: { index: true } */
            var accepted = false;

            /* ---------- Tiện ích ---------- */
            function esc(s) {
                return String(s === undefined || s === null ? '' : s)
                    .replace(/&/g, '&amp;')
                    .replace(/</g, '&lt;')
                    .replace(/>/g, '&gt;');
            }

            function field(arr, i) {
                if (!arr || i < 0 || i >= arr.length) return '';
                var v = arr[i];
                if (v === undefined || v === null) return '';
                return String(v).trim();
            }

            function starsText(n) {
                var s = '';
                for (var i = 0; i < n; i++) s += '★';
                return s;
            }

            /* ---------- Phân tích cú pháp ---------- */
            function parseRecords(raw) {
                var out = [];
                var lineRe = /\[([^\]]*)\]/g;
                var m;
                while ((m = lineRe.exec(raw)) !== null) {
                    var parts = m[1].split('|');
                    if (parts.length < 3) continue;

                    /* Độ nguy hiểm có thể viết là "★5" (dấu sao + số), cũng có thể viết là "★★★★★", cả hai đều lấy giá trị lớn hơn */
                    var threatRaw = field(parts, 4);
                    var stars = (threatRaw.match(/★/g) || []).length;
                    var starNum = threatRaw.match(/([0-9]+)/);
                    if (starNum) {
                        var n = parseInt(starNum[1], 10);
                        if (n > stars) stars = n;
                    }
                    if (threatRaw === '') stars = 0;
                    if (stars > 9) stars = 9;
                    if (stars < 0) stars = 0;

                    var lvRaw = field(parts, 3).toUpperCase();
                    var lv = lvRaw.charAt(0);
                    if (LEVELS.indexOf(lv) < 0) lv = '';

                    var rec = {
                        idx: out.length,
                        type: field(parts, 0) || 'Treo thưởng',
                        code: field(parts, 1),
                        title: field(parts, 2) || 'Ủy thác vô danh',
                        level: lv,
                        stars: stars,
                        threat: threatRaw,
                        region: field(parts, 5),
                        detail: field(parts, 6),
                        mats: field(parts, 7),
                        reward: field(parts, 8),
                        place: field(parts, 9),
                        goal: field(parts, 10)
                    };
                    rec.search = (rec.title + ' ' + rec.detail + ' ' + rec.region + ' ' + rec.mats).toLowerCase();
                    out.push(rec);
                }
                return out;
            }

            /* ---------- Render thẻ ---------- */
            function rowHtml(key, val) {
                if (!val) return '';
                return '<div class="hnt-row"><span class="hnt-key">' + esc(key) + '</span><span class="hnt-val">' + esc(val) + '</span></div>';
            }

            function renderCards() {
                var html = '';
                for (var i = 0; i < records.length; i++) {
                    var r = records[i];
                    var stars = r.stars > 0 ? starsText(r.stars) : '—';
                    var metaBits = [];
                    if (r.code) metaBits.push(r.code);
                    metaBits.push(r.type);
                    if (r.goal) metaBits.push(r.goal);

                    html += '<div class="hnt-card" data-idx="' + r.idx + '">'
                        + '<div class="hnt-card-head">'
                        +   '<div class="hnt-seal hnt-seal-' + (r.level || 'X') + '"><span>' + (r.level || '?') + '</span></div>'
                        +   '<div class="hnt-head-text">'
                        +     '<div class="hnt-card-title">' + esc(r.title) + '</div>'
                        +     '<div class="hnt-card-meta">' + esc(metaBits.join(' · ')) + '</div>'
                        +   '</div>'
                        +   '<div class="hnt-stars">' + stars + '</div>'
                        + '</div>'
                        + '<div class="hnt-rows">'
                        +   rowHtml('Khu vực săn bắn', r.region)
                        +   rowHtml('Chi tiết ủy thác', r.detail)
                        +   rowHtml('Nguyên liệu chỉ định', r.mats)
                        +   rowHtml('Phần thưởng', r.reward)
                        +   rowHtml('Địa điểm nhận', r.place)
                        +   rowHtml('Điều kiện đạt được', r.goal)
                        + '</div>'
                        + '</div>';
                }
                $list.html(html);
            }

            /* ---------- Bộ điều khiển lọc ---------- */
            function buildGroup($box, items, key) {
                $box.empty();
                for (var i = 0; i < items.length; i++) {
                    (function (val, label) {
                        var cls = 'hnt-fbtn' + (val === state[key] ? ' hnt-on' : '');
                        $('<button type="button" class="' + cls + '">' + esc(label) + '</button>')
                            .on('click', function () {
                                state[key] = val;
                                $box.find('.hnt-fbtn').removeClass('hnt-on');
                                $(this).addClass('hnt-on');
                                applyFilters();
                            })
                            .appendTo($box);
                    })(items[i][0], items[i][1]);
                }
            }

            function regionFilters() {
                var list = [['all', 'Tất cả']];
                var seen = {};
                for (var i = 0; i < records.length; i++) {
                    var rg = records[i].region;
                    if (!rg || seen[rg]) continue;
                    seen[rg] = true;
                    list.push([rg, rg]);
                }
                return list;
            }

            function renderGroups() {
                buildGroup($root.find('.hnt-fgroup-star'), STAR_FILTERS, 'star');
                buildGroup($root.find('.hnt-fgroup-level'), LEVEL_FILTERS, 'level');
                buildGroup($root.find('.hnt-fgroup-region'), regionFilters(), 'region');
            }

            /* ---------- Logic lọc ---------- */
            function matchStar(r) {
                var s = r.stars;
                if (state.star === '1-2') return s >= 1 && s <= 2;
                if (state.star === '3-4') return s >= 3 && s <= 4;
                if (state.star === '5-6') return s >= 5 && s <= 6;
                if (state.star === '7+') return s >= 7;
                return true;
            }

            function applyFilters() {
                var visible = 0;
                $list.children('.hnt-card').each(function () {
                    var $card = $(this);
                    var r = records[parseInt($card.attr('data-idx'), 10)];
                    if (!r) { $card.hide(); return; }
                    var ok = true;
                    if (state.q && r.search.indexOf(state.q) < 0) ok = false;
                    if (ok && state.star !== 'all' && !matchStar(r)) ok = false;
                    if (ok && state.level !== 'all' && r.level !== state.level) ok = false;
                    if (ok && state.region !== 'all' && r.region !== state.region) ok = false;
                    if (ok) { $card.show(); visible++; } else { $card.hide(); }
                });

                if (records.length === 0) {
                    $empty.text('Chưa lấy được dữ liệu treo thưởng').show();
                } else if (visible === 0) {
                    $empty.text('Không có ủy thác phù hợp điều kiện').show();
                } else {
                    $empty.hide();
                }

                /* Chọn nhiều: Thẻ bị lọc ra vẫn giữ trạng thái chọn, tiện cho việc "lọc một đợt → chọn tất cả → lọc tiếp đợt sau" */
                syncAccept();
            }

            /* ---------- Đã chọn / Trạng thái nút ---------- */
            function selectedList() {
                var out = [];
                for (var k in selected) if (selected[k]) out.push(parseInt(k, 10));
                out.sort(function (a, b) { return a - b; });
                return out;
            }

            function clearSelection() {
                selected = {};
                $list.children('.hnt-card').removeClass('hnt-selected');
            }

            function visibleIdx() {
                var out = [];
                $list.children('.hnt-card').each(function () {
                    var $c = $(this);
                    if ($c.is(':hidden')) return;
                    var i = parseInt($c.attr('data-idx'), 10);
                    if (!isNaN(i)) out.push(i);
                });
                return out;
            }

            function allVisibleSelected() {
                var v = visibleIdx();
                if (!v.length) return false;
                for (var i = 0; i < v.length; i++) if (!selected[v[i]]) return false;
                return true;
            }

            function syncAccept() {
                var n = selectedList().length;
                if (accepted) {
                    $accept.prop('disabled', true).removeClass('hnt-ready').text('Đã lưu vào bản nháp');
                } else if (n === 0) {
                    $accept.prop('disabled', true).removeClass('hnt-ready').text('Tiếp nhận ủy thác');
                } else {
                    $accept.prop('disabled', false).addClass('hnt-ready').text('Tiếp nhận ủy thác (' + n + ')');
                }
                if ($selinfo.length) {
                    if (accepted) {
                        $selinfo.text('Đã lưu ' + n + ' ủy thác vào bản nháp').addClass('hnt-has');
                    } else if (n === 0) {
                        $selinfo.text('Chưa chọn ủy thác · Nhấp thẻ để chọn nhiều').removeClass('hnt-has');
                    } else {
                        $selinfo.text('Đã chọn ' + n + ' ủy thác').addClass('hnt-has');
                    }
                }
                if ($selall.length) {
                    $selall.text(allVisibleSelected() ? 'Bỏ chọn tất cả' : 'Chọn tất cả hiển thị');
                }
            }

            /* ---------- Điền lại khung nhập ---------- */
            function fillInput(text) {
                try {
                    var textarea = window.parent.document.querySelector('#send_textarea');
                    if (textarea) {
                        var old = textarea.value.trim();
                        textarea.value = old ? old + "\n" + text : text;
                        textarea.dispatchEvent(new Event('input', { bubbles: true }));
                        return true;
                    }
                } catch (e) { }
                return false;
            }

            /* ---------- Ràng buộc sự kiện ---------- */
            /* Chọn nhiều: Nhấp thẻ để chuyển đổi trạng thái chọn, không loại trừ lẫn nhau */
            $list.on('click', '.hnt-card', function () {
                var $card = $(this);
                var idx = parseInt($card.attr('data-idx'), 10);
                if (isNaN(idx)) return;
                if (selected[idx]) {
                    delete selected[idx];
                    $card.removeClass('hnt-selected');
                } else {
                    selected[idx] = true;
                    $card.addClass('hnt-selected');
                }
                accepted = false;   /* Sau khi chọn lại cho phép tiếp nhận ủy thác lần nữa */
                syncAccept();
            });

            $selall.on('click', function () {
                var v = visibleIdx();
                if (allVisibleSelected()) {
                    for (var i = 0; i < v.length; i++) delete selected[v[i]];
                    $list.children('.hnt-card').each(function () {
                        var $c = $(this);
                        var j = parseInt($c.attr('data-idx'), 10);
                        if (v.indexOf(j) >= 0) $c.removeClass('hnt-selected');
                    });
                } else {
                    for (var k = 0; k < v.length; k++) selected[v[k]] = true;
                    $list.children('.hnt-card').each(function () {
                        var $c = $(this);
                        var j = parseInt($c.attr('data-idx'), 10);
                        if (v.indexOf(j) >= 0) $c.addClass('hnt-selected');
                    });
                }
                accepted = false;
                syncAccept();
            });

            $search.on('input', function () {
                state.q = String($(this).val() || '').toLowerCase().trim();
                applyFilters();
            });

            $root.find('.hnt-clear').on('click', function () {
                state = { q: '', star: 'all', level: 'all', region: 'all' };
                $search.val('');
                renderGroups();
                applyFilters();
            });

            /* Tiếp nhận ủy thác: Xuất mỗi ủy thác đã chọn thành một dòng lệnh 【Tiếp nhận ủy thác】 */
            function acceptLine(r) {
                var head = (r.code ? r.code + ' ' : '') + r.title;
                var lvText = r.level ? 'Cấp ' + r.level : 'Cấp chưa xác định';
                var starText = r.threat ? r.threat : (r.stars > 0 ? starsText(r.stars) : 'Mối đe dọa chưa rõ');
                return '【Tiếp nhận ủy thác】' + head + ' ｜ ' + lvText + ' ｜ ' + starText + ' ｜ '
                    + (r.region || 'Khu vực chưa rõ') + ' ｜ ' + (r.goal || 'Điều kiện đạt được chưa định') + ' ｜ Phần thưởng ' + (r.reward || 'chưa định');
            }

            $accept.on('click', function () {
                if (accepted) return;
                var idxs = selectedList();
                if (!idxs.length) return;

                var lines = [];
                for (var i = 0; i < idxs.length; i++) {
                    var r = records[idxs[i]];
                    if (r) lines.push(acceptLine(r));
                }
                if (!lines.length) return;

                accepted = fillInput(lines.join('\n'));
                if (accepted) {
                    clearSelection();
                }
                syncAccept();
            });

            $refresh.on('click', function () {
                fillInput('【Làm mới bảng treo thưởng】');
            });

            /* ---------- Khởi động ---------- */
            records = parseRecords(rawContent);
            renderCards();
            renderGroups();
            applyFilters();
            syncAccept();
        });
    </script>
</body>
</html>
