<script>
(function () {
  'use strict';

  var QC = {
    'Phổ thông': '#9aa0a6', 'Ưu tú': '#6fae5a', 'Hiếm': '#4a90d9', 'Sử thi': '#a35fd6',
    'Truyền thuyết': '#d4a24c', 'Thần thoại': '#e0503a', 'Duy nhất': '#e0c04a'
  };
  var QD = '#9aa0a6';

  var boxes = document.querySelectorAll('[data-hnt="result"]:not([data-done])');
  for (var bi = 0; bi < boxes.length; bi++) {
    (function (box) {
      box.setAttribute('data-done', '1');
      try {
        var fallback = box.nextElementSibling;
        while (fallback && !(fallback.classList && fallback.classList.contains('hnt-fallback'))) fallback = fallback.nextElementSibling;

        var bodyEl = box.querySelector('.hnt-body');
        var questEl = box.querySelector('.hnt-quest');
        var metaEl = box.querySelector('.hnt-meta');
        var stampEl = box.querySelector('.hnt-stamp');
        var btn = box.querySelector('.hnt-btn');

        if (!bodyEl) throw new Error('Không tìm thấy .hnt-body');
        if (!fallback) throw new Error('Không tìm thấy vùng chứa dữ liệu .hnt-fallback');

        var raw = String(fallback.textContent || '');

        function esc(s) {
          return String(s === null || s === undefined ? '' : s)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;')
            .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
        }
        function trim(s) { return String(s === null || s === undefined ? '' : s).replace(/^\s+|\s+$/g, ''); }

        var recs = [];
        var re = /\[([^\[\]]*)\]/g, m;
        while ((m = re.exec(raw)) !== null) {
          var f = m[1].split('|');
          for (var i = 0; i < f.length; i++) f[i] = trim(f[i]);
          if (f[0]) recs.push({ t: f[0], f: f });
        }

        var sum = null, parts = [], drops = [], rew = null, codex = [];
        for (var k = 0; k < recs.length; k++) {
          var ty = recs[k].t;
          if (ty === 'Kết toán') { if (!sum) sum = recs[k]; }
          else if (ty === 'Bộ phận') parts.push(recs[k]);
          else if (ty === 'Lột lấy') drops.push(recs[k]);
          else if (ty === 'Thù lao') { if (!rew) rew = recs[k]; }
          else if (ty === 'Minh họa') codex.push(recs[k]);
        }
        function g(r, i) { var v = r.f[i]; return (v === undefined || v === null) ? '' : v; }

        var quest = sum ? g(sum, 1) : '';
        var rank = sum ? g(sum, 2) : '';
        var verdict = sum ? g(sum, 3) : '';
        var how = sum ? g(sum, 4) : '';
        var place = sum ? g(sum, 5) : '';
        var isFail = verdict.indexOf('Thất bại') > -1;

        if (questEl) questEl.textContent = quest || 'Kết quả săn bắn';
        var metaBits = [];
        if (rank) metaBits.push('Cấp ' + rank);
        if (how) metaBits.push(how);
        if (place) metaBits.push(place);
        if (metaEl) metaEl.textContent = metaBits.join(' · ');
        if (stampEl) {
          stampEl.textContent = verdict || (isFail ? 'Thất bại' : 'Thành công');
          stampEl.className = 'hnt-stamp ' + (isFail ? 'hnt-stamp-ng' : 'hnt-stamp-ok');
        }

        var html = '';

        if (parts.length) {
          html += '<div class="hnt-sec"><div class="hnt-sec-t">Phá hủy bộ phận</div>';
          for (var p = 0; p < parts.length; p++) {
            var nm = g(parts[p], 1), st = g(parts[p], 2), out = g(parts[p], 3);
            var ok = st.indexOf('Chưa') === -1 && st.indexOf('Đã') > -1;
            html += '<div class="hnt-line">' +
              '<span class="hnt-dot ' + (ok ? 'hnt-dot-ok' : 'hnt-dot-no') + '">' + (ok ? '✓' : '○') + '</span>' +
              '<span class="hnt-line-n">' + esc(nm) + '</span>' +
              '<span class="hnt-line-x">' + esc(!ok || !out || out === '-' ? '—' : out) + '</span></div>';
          }
          html += '</div>';
        }

        if (drops.length) {
          html += '<div class="hnt-sec"><div class="hnt-sec-t">Nguyên liệu lột lấy</div>';
          for (var d = 0; d < drops.length; d++) {
            var mn = g(drops[d], 1), mq = g(drops[d], 2), ql = g(drops[d], 3);
            var col = QC[ql] || QD;
            html += '<div class="hnt-line">' +
              '<span class="hnt-dot" style="color:' + col + '">◆</span>' +
              '<span class="hnt-line-n">' + esc(mn) + '</span>' +
              (ql ? '<span class="hnt-q" style="color:' + col + ';border-color:' + col + '">' + esc(ql) + '</span>' : '') +
              '<span class="hnt-qty">×' + esc(mq || '1') + '</span></div>';
          }
          html += '</div>';
        }

        if (rew) {
          var rv = g(rew, 1), rc = g(rew, 2), rl = g(rew, 3);
          html += '<div class="hnt-sec"><div class="hnt-sec-t">Thù lao</div>';
          if (/^[0-9,，]+$/.test(rv)) {
            html += '<div class="hnt-rew"><span class="hnt-rew-n">' + esc(rv) + '</span>' +
              (rc ? '<span class="hnt-rew-c">' + esc(rc) + '</span>' : '') +
              (rl ? '<span class="hnt-rew-l">' + esc(rl) + '</span>' : '') + '</div>';
          } else {
            html += '<div class="hnt-rew"><span class="hnt-rew-l">' + esc(rv || 'Không') + '</span></div>';
          }
          html += '</div>';
        }

        if (codex.length) {
          html += '<div class="hnt-sec"><div class="hnt-sec-t">Biến động minh họa</div>';
          for (var c = 0; c < codex.length; c++) {
            html += '<div class="hnt-cx"><div class="hnt-cx-n">' + esc(g(codex[c], 1)) + '</div>' +
              '<div class="hnt-cx-w">' + esc(g(codex[c], 2)) + '</div>' +
              (g(codex[c], 3) ? '<div class="hnt-cx-s">' + esc(g(codex[c], 3)) + '</div>' : '') +
              '</div>';
          }
          html += '</div>';
        }

        if (!parts.length && !drops.length && !rew && !codex.length) {
          html = '<div class="hnt-empty">Không tìm thấy bản ghi kết toán</div>';
        }

        bodyEl.innerHTML = html;

        if (fallback && fallback.parentNode) fallback.parentNode.removeChild(fallback);

        if (btn) {
          btn.addEventListener('click', function () {
            var txt = '【Minh Họa Thợ Săn】';
            var done = false;
            try {
              var doc = (window.parent && window.parent !== window) ? window.parent.document : document;
              var ta = doc.querySelector('#send_textarea') || doc.getElementById('send_textarea');
              if (ta) {
                var old = String(ta.value || '').replace(/\s+$/, '');
                ta.value = old ? old + '\n' + txt : txt;
                ta.dispatchEvent(new Event('input', { bubbles: true }));
                done = true;
              }
            } catch (e) {}
            if (done) {
              btn.textContent = 'Đã điền vào khung nhập';
              btn.classList.add('hnt-done');
              setTimeout(function () { btn.textContent = 'Xem Minh Họa'; btn.classList.remove('hnt-done'); }, 1600);
            } else {
              btn.textContent = 'Ghi thất bại · Vui lòng nhập thủ công';
              setTimeout(function () { btn.textContent = 'Xem Minh Họa'; }, 2000);
            }
          });
        }
      } catch (err) {
        try {
          var d = document.createElement('div');
          d.className = 'hnt-err';
          d.textContent = 'Hiển thị bảng kết toán thất bại: ' + ((err && err.message) ? err.message : String(err));
          (box.querySelector('.hnt-board') || box).appendChild(d);
        } catch (e2) {}
      }
    })(boxes[bi]);
  }
})();
</script>
</body>
</html>
