.bh-claim {
  display: block; margin: 12px auto 2px; padding: 8px 34px; cursor: pointer;
  font-family: inherit; font-size: 15px; font-weight: 700; letter-spacing: 0.5em; text-indent: 0.5em;
  color: #f5e3c8; background: linear-gradient(180deg, #a03a2c, #7c2418);
  border: 1px solid #5c1810; border-radius: 4px;
  box-shadow: 0 4px 9px rgba(60, 20, 10, 0.4), inset 0 1px 0 rgba(255, 220, 180, 0.3);
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.45); transition: transform 0.15s ease, filter 0.15s ease;
}
.bh-claim:hover { filter: brightness(1.12); transform: translateY(-1px); }
.bh-claim:active { transform: translateY(1px); }
.bh-claim[data-state="done"] {
  cursor: default; color: #efe4c8; background: linear-gradient(180deg, #7a6a45, #5c4e30);
  border-color: #4a3e22; letter-spacing: 0.2em; text-indent: 0.2em; font-size: 13px;
}
.bh-claim[data-state="done"]:hover { filter: none; transform: none; }
.bh-claim[data-state="busy"] { pointer-events: none; filter: brightness(0.85); }
.bh-claim[data-state="blocked"] { cursor: not-allowed; background: linear-gradient(180deg, #8a8272, #6a6252); border-color: #524a3a; }

/* ---------- 线索渠道 / 守则 ---------- */
.bh-plain {
  margin: 6px 30px; padding: 7px 12px; font-size: 13px; line-height: 1.9; color: #4a3a1c;
  border-left: 3px double #a08048; background: rgba(122, 92, 48, 0.07);
}
.bh-note { text-align: center; font-size: 11.5px; color: #8a744a; margin: 14px 30px 0; letter-spacing: 0.08em; }

/* ---------- 提示条 ---------- */
.bh-tip {
  position: fixed; left: 50%; bottom: 26px; transform: translateX(-50%);
  max-width: 82%; padding: 9px 18px; border-radius: 4px; z-index: 99;
  font-size: 13.5px; line-height: 1.7; color: #f0e4c4; text-align: center;
  background: rgba(30, 20, 8, 0.92); border: 1px solid rgba(216, 170, 100, 0.5);
  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.5); opacity: 0; pointer-events: none;
  transition: opacity 0.25s ease, bottom 0.25s ease;
}
.bh-tip.show { opacity: 1; bottom: 34px; }
.bh-tip.err { color: #f2b8a8; border-color: rgba(190, 90, 60, 0.6); }

/* ---------- 入场 ---------- */
@keyframes bhIn { from { opacity: 0; transform: translateY(-7px); } to { opacity: 1; transform: none; } }
.bh-card { animation: bhIn 0.4s ease-out both; }

/* ---------- 窄屏 ---------- */
@media (max-width: 640px) {
  .bh-board { margin: 10px 6px; }
  .bh-head h1 { font-size: 24px; letter-spacing: 0.28em; text-indent: 0.28em; }
  .bh-seal { width: 58px; height: 58px; font-size: 20px; right: 14px; top: 12px; }
  .bh-card { padding: 14px 12px 12px 18px; }
  .bh-tier { width: 48px; height: 48px; font-size: 9.5px; }
  .bh-sec { margin: 18px 16px 6px; letter-spacing: 0.18em; }
  .bh-plain { margin: 6px 16px; }
}

</style>
</head>
<body>
<div data-bh-root="board"></div>
<textarea id="bh-raw" style="display:none">$0</textarea>
<script>
/* ============================================================
 * 赏金公所 · 面板逻辑（酒馆助手 iframe 内运行）
 * 铁律：本文件任何位置不得出现「美元符号紧跟数字」——
 *       整个文件会被嵌入 replaceString，ST 会替换所有此类序列。
 *       另：禁止预编码 HTML 实体，和号用 '\u0026' 运行时拼。
 * ============================================================ */
(function () {
    'use strict';

    /* ---------- 工具 ---------- */
    var AMP = '\u0026';
    var ESC_MAP = { '&': AMP + 'amp;', '<': AMP + 'lt;', '>': AMP + 'gt;', '"': AMP + 'quot;', "'": AMP + '#39;' };
    function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return ESC_MAP[c]; }); }

    /* 蜡印配色（级别 → 高光/主色/暗部/字色） */
    var WAX = {
        '白铁级': ['#b6bcc6', '#8a909a', '#5a606a', '#2c2f34'],
        '赤铜级': ['#e0a05e', '#b87333', '#8a5424', '#f7ecd6'],
        '白银级': ['#eef1f5', '#c0c6ce', '#98a0aa', '#3a3f47'],
        '黄金级': ['#f4dc82', '#d4af37', '#a8862a', '#4a3a10'],
        '血金级': ['#d0604a', '#a02c2c', '#701c14', '#f7ecd6'],
        '玄冕级': ['#9a7ad0', '#5a3d92', '#3d2b52', '#efe4f8']
    };
    var TIER_RANK = { '白铁级': '低', '赤铜级': '中', '白银级': '中', '黄金级': '高', '血金级': '高', '玄冕级': '高' };
    var TASK_CAP = 3;   /* MVU 规则：避免一次性添加超过3个任务 */

    /* ---------- 载荷解析 ---------- */
    function splitCells(line) {
        var s = String(line).trim();
        if (s.charAt(0) === '|') s = s.slice(1);
        if (s.charAt(s.length - 1) === '|') s = s.slice(0, -1);
        return s.split('|').map(function (c) { return c.trim(); }).filter(Boolean).map(function (cell) {
            var i = cell.search(/[:：]/);
            if (i < 0) return { k: '', v: cell };
            return { k: cell.slice(0, i).trim(), v: cell.slice(i + 1).trim() };
        });
    }

    function parsePayload(text) {
        var clean = String(text || '').replace(/<\/?bounty_info>/gi, '').replace(/\r/g, '');
        var sections = [], cur = null;
        var lines = clean.split('\n');
        for (var i = 0; i < lines.length; i++) {
            var line = lines[i].trim();
            if (!line) continue;
            var ms = line.match(/^\{(.+?)\}$/);
            if (ms) { cur = { title: ms[1], rows: [] }; sections.push(cur); continue; }
            if (line.charAt(0) !== '|') continue;
            if (!cur) { cur = { title: '', rows: [] }; sections.push(cur); }
            var cells = splitCells(line);
            if (cells.length) cur.rows.push(cells);
        }
        return sections;
    }

    function findSection(sections, title) {
        for (var i = 0; i < sections.length; i++) if (sections[i].title === title) return sections[i];
        return null;
    }

    /* ---------- 卡片模型 ---------- */
    function collectCards(sections) {
        var sec = findSection(sections, '通缉榜');
        var cards = [], cur = null;
        if (!sec) return cards;
        sec.rows.forEach(function (row) {
            var flat = {};
            var hasNo = false;
            row.forEach(function (c) { flat[c.k || '条目'] = c.v; if (c.k === '编号') hasNo = true; });
            if (hasNo || !cur) {
                cur = { fields: {}, secrets: [] };
                cards.push(cur);
            }
            if (!cur) return;
            Object.keys(flat).forEach(function (k) {
                if (k === '条目') return;
                if (k.indexOf('密档') === 0) {
                    cur.secrets.push({ label: k.replace(/^密档[·:：]?\s*/, ''), v: flat[k] });
                } else {
                    cur.fields[k] = flat[k];
                }
            });
        });
        return cards.filter(function (c) { return c.fields['编号']; });
    }

    function taskKey(card) {
        var no = card.fields['编号'] || '';
        return ('通缉·' + (card.fields['名讳'] || '未知') + '（' + no + '）').replace(/\./g, '·');
    }

    function isLocked(v) { return v == null || v === '' || v === '???' || v === '？？？' || /未查明/.test(v); }

    function buildTask(card) {
        var f = card.fields;
        var total = card.secrets.length;
        var locked = card.secrets.filter(function (s) { return isLocked(s.v); }).length;
        var known = total - locked;
        var level = f['级别'] || '';
        var task = {
            状态: '进行中·已揭榜',
            关注度: TIER_RANK[level] || '中',
            进展: '已揭榜；已明线索 ' + known + '/' + total +
                (locked > 0 ? '（尚有 ' + locked + ' 项密档未查明，信息差风险自担）' : ''),
            详情: '赏金公所通缉令 ' + (f['编号'] || '') + '｜' + level + '｜罪名: ' + (f['罪名'] || '') +
                '｜交付: ' + (f['交付'] || '死活不论') + '｜发布: ' + (f['发布'] || '不详'),
            目标: '缉拿并按「' + (f['交付'] || '死活不论') + '」交付「' + (f['名讳'] || '') + '」；' +
                '当前线索 ' + known + '/' + total +
                (locked > 1 ? '，强烈建议先补齐密档再行动' : locked > 0 ? '，可尝试但需承担信息差' : '') +
                '；时限: ' + (f['时限'] || '未载明'),
            奖励: (f['悬赏'] || '面议') + '；凭编号 ' + (f['编号'] || '') + ' 至原公所结付'
        };
        return task;
    }

    /* ---------- 渲染 ---------- */
    function dotsHtml(card) {
        var f = card.fields;
        var m = String(f['线索'] || '0/0').match(/(\d+)\s*\/\s*(\d+)/);
        var known = m ? Number(m[1]) : 0, total = m ? Number(m[2]) : 0;
        var out = '<span class="bh-dots">';
        for (var i = 0; i < total; i++) out += '<i class="' + (i < known ? 'on' : '') + '"></i>';
        out += '<em>已明 ' + known + '／共 ' + total + '</em></span>';
        return out;
    }

    function cardHtml(card) {
        var f = card.fields;
        var level = f['级别'] || '';
        var wax = WAX[level] || WAX['赤铜级'];
        var secrets = card.secrets.map(function (s) {
            var locked = isLocked(s.v);
            return '<div class="bh-secret"><b>密档·' + esc(s.label) + '</b>' +
                (locked
                    ? '<span class="bh-locked">' + esc(s.v || '？？？') + '</span><small>未查明</small>'
                    : '<span class="bh-open">' + esc(s.v) + '</span>') +
                '</div>';
        }).join('');
        var known = String(f['众知'] || '');
        var html = '<div class="bh-card" data-no="' + esc(f['编号'] || '') + '">'
            + '<div class="bh-tier" style="--wax-hi:' + wax[0] + ';--wax:' + wax[1] + ';--wax-lo:' + wax[2] + ';color:' + wax[3] + '">'
            + '<b>' + esc(level.replace(/级$/, '')) + '</b>' + esc(level) + '</div>'
            + '<div class="bh-stamp" data-d="' + esc(f['交付'] || '死活不论') + '">' + esc(f['交付'] || '死活不论') + '</div>'
            + '<div class="bh-wanted">通　缉</div>'
            + '<div class="bh-name"><span class="bh-nm">' + esc(f['名讳'] || '无名氏') + '</span><small>' + esc(f['编号'] || '') + '</small></div>'
            + '<div class="bh-kv"><b>罪　名</b><i>' + esc(f['罪名'] || '—') + '</i></div>'
            + '<div class="bh-kv"><b>悬　赏</b><i><span class="bh-gold">' + esc(f['悬赏'] || '面议') + '</span>' + dotsHtml(card) + '</i></div>'
            + (known ? '<div class="bh-known">众知：' + esc(known) + '</div>' : '')
            + secrets
            + '<div class="bh-kv"><b>发　布</b><i>' + esc(f['发布'] || '—') + '</i></div>'
            + '<div class="bh-kv"><b>时　限</b><i>' + esc(f['时限'] || '未载明') + '</i></div>'
            + '<button class="bh-claim" type="button" data-state="idle">揭　榜</button>'
            + '</div>';
        return html;
    }

    function sectionRows(sec, cls) {
        if (!sec) return '';
        return sec.rows.map(function (row) {
            return '<div class="' + cls + '">' + row.map(function (c) {
                return c.k ? '<b>' + esc(c.k) + '</b>　' + esc(c.v) : esc(c.v);
            }).join('；') + '</div>';
        }).join('');
    }

    function renderFromRaw(raw) {
        var sections = parsePayload(raw);
        var office = findSection(sections, '赏金公所');
        var cards = collectCards(sections);
        var channels = findSection(sections, '线索渠道');
        var html = '<div class="bh-board">'
            + '<div class="bh-head"><h1>赏金公所<span>·缉捕榜</span></h1>'
            + '<div class="bh-sub">'
            + (office ? office.rows.map(function (row) {
                return row.map(function (c) { return c.k ? esc(c.k) + '｜' + esc(c.v) : esc(c.v); }).join('　');
              }).join('　')
            : '今日无榜') + '</div>'
            + '<div class="bh-rule-line"></div>'
            + '<div class="bh-seal">缉</div></div>'
            + '<div class="bh-sec">通缉榜</div>'
            + (cards.length
                ? cards.map(cardHtml).join('')
                : '<div class="bh-plain">今日榜上无人。去别处转转，或等执榜人换一批新的。</div>')
            + '<div class="bh-sec">线索渠道</div>'
            + sectionRows(channels, 'bh-plain')
            + '<div class="bh-sec">猎人守则</div>'
            + '<div class="bh-plain">杀良冒功者吊销猎籍、追缴全部赏金并依律论处；一榜不得双花；黑吃黑不受公所保护。密档未查明的榜，风险自负——公所不管埋伏。</div>'
            + '<div class="bh-note">—— 赏金公所谨识 · 揭榜即立约 ——</div>'
            + '</div>'
            + '<div class="bh-tip" id="bh-tip"></div>';
        return html;
    }

    /* ---------- 运行环境（酒馆助手 / MVU） ---------- */
    function getAPI() {
        if (typeof window.Mvu !== 'undefined' || typeof window.waitGlobalInitialized !== 'undefined') return window;
        try { if (window.parent && window.parent.Mvu) return window.parent; } catch (e) { }
        try { if (window.top && window.top.Mvu) return window.top; } catch (e) { }
        return null;
    }

    var TOAST_TIMER = null;
    function toast(msg, isErr) {
        var el = document.getElementById('bh-tip');
        if (!el) return;
        el.textContent = msg;
        el.className = 'bh-tip show' + (isErr ? ' err' : '');
        if (TOAST_TIMER) clearTimeout(TOAST_TIMER);
        TOAST_TIMER = setTimeout(function () { el.className = 'bh-tip'; }, 3600);
    }

    /* ---------- 揭榜（写 MVU 变量） ---------- */
    async function claim(card, btn) {
        var H = getAPI();
        if (!H || typeof H.Mvu === 'undefined') {
            toast('未检测到 MVU 变量框架——请在酒馆内使用（需安装 MVU 变量框架脚本）', true);
            return;
        }
        btn.dataset.state = 'busy';
        try {
            try { await H.waitGlobalInitialized('Mvu'); } catch (e) { }
            var data = H.Mvu.getMvuData({ type: 'message', message_id: 'latest' });
            if (!data.stat_data) data.stat_data = {};
            if (!data.stat_data['任务列表']) data.stat_data['任务列表'] = {};
            var tasks = data.stat_data['任务列表'];
            var key = taskKey(card);
            if (tasks[key]) {
                btn.dataset.state = 'done';
                btn.textContent = '已在任务簿';
                toast('这张榜你已揭过——任务簿里见。', true);
                return;
            }
            var count = Object.keys(tasks).length;
            if (count >= TASK_CAP) {
                btn.dataset.state = 'blocked';
                btn.textContent = '任务簿已满';
                toast('任务簿已有 ' + count + ' 项在手——依公所规矩，先结清或了结在手任务，再来揭榜', true);
                return;
            }
            tasks[key] = buildTask(card);
            await H.Mvu.replaceMvuData(data, { type: 'message', message_id: 'latest' });
            btn.dataset.state = 'done';
            btn.textContent = '已录入任务簿';
            toast('已录入任务簿：' + key + '——去把人带回来。');
        } catch (e) {
            btn.dataset.state = 'idle';
            toast('揭榜失败：' + ((e && e.message) || e), true);
        }
    }

    /* ---------- 状态刷新（已揭过榜的卡置灰） ---------- */
    async function refreshClaimState(root) {
        var H = getAPI();
        if (!H || typeof H.Mvu === 'undefined') return;
        try {
            try { await H.waitGlobalInitialized('Mvu'); } catch (e) { }
            var data = H.Mvu.getMvuData({ type: 'message', message_id: 'latest' });
            var tasks = (data.stat_data && data.stat_data['任务列表']) || {};
            var full = Object.keys(tasks).length >= TASK_CAP;
            root.querySelectorAll('.bh-card').forEach(function (el) {
                var no = el.getAttribute('data-no');
                var nameEl = el.querySelector('.bh-nm');
                if (!no || !nameEl) return;
                var name = (nameEl.textContent || '').trim();
                var key = ('通缉·' + name + '（' + no + '）').replace(/\./g, '·');
                var btn = el.querySelector('.bh-claim');
                if (!btn) return;
                if (tasks[key]) {
                    btn.dataset.state = 'done';
                    btn.textContent = '已在任务簿';
                } else if (full) {
                    btn.dataset.state = 'blocked';
                    btn.textContent = '任务簿已满';
                }
            });
        } catch (e) { /* 预览环境静默 */ }
    }

    function bind(root) {
        root.querySelectorAll('.bh-card').forEach(function (el) {
            var btn = el.querySelector('.bh-claim');
            if (!btn) return;
            btn.addEventListener('click', function () {
                if (btn.dataset.state === 'done' || btn.dataset.state === 'busy') return;
                var no = el.getAttribute('data-no') || '';
                var card = { fields: {}, secrets: [] };
                el.querySelectorAll('.bh-kv, .bh-secret').forEach(function (row) {
                    var b = row.querySelector('b'), v = row.querySelector('i, .bh-open, .bh-locked');
                    if (!b || !v) return;
                    var k = (b.textContent || '').replace(/[\s　]/g, '').replace('密档·', '');
                    if (k === '罪名') card.fields['罪名'] = (v.textContent || '').trim();
                    else if (k === '悬赏') {
                        var gold = row.querySelector('.bh-gold');
                        card.fields['悬赏'] = (gold ? gold.textContent : v.textContent).trim();
                    }
                    else if (k === '发布') card.fields['发布'] = (v.textContent || '').trim();
                    else if (k === '时限') card.fields['时限'] = (v.textContent || '').trim();
                    else if (b.textContent.indexOf('密档') === 0) card.secrets.push({ label: k, v: (v.textContent || '').trim() });
                });
                var nameEl = el.querySelector('.bh-nm');
                card.fields['名讳'] = (nameEl ? nameEl.textContent : '').trim();
                card.fields['编号'] = no;
                var st = el.querySelector('.bh-stamp');
                card.fields['交付'] = st ? st.textContent.trim() : '死活不论';
                var tierEl = el.querySelector('.bh-tier b');
                card.fields['级别'] = tierEl ? (tierEl.textContent.trim() + '级') : '';
                var dots = el.querySelector('.bh-dots em');
                var dm = (dots ? dots.textContent : '').match(/(\d+)\s*／\s*(\d+)/);
                card.fields['线索'] = dm ? (dm[1] + '/' + dm[2]) : '0/0';
                claim(card, btn);
            });
        });
    }

    /* ---------- 启动 ---------- */
    function boot() {
        var root = document.querySelector('[data-bh-root]');
        if (!root) return;
        var rawEl = document.getElementById('bh-raw');
        var raw = rawEl ? rawEl.value : '';
        if (typeof window.__BH__ !== 'undefined') window.__BH__.raw = raw;
        root.innerHTML = renderFromRaw(raw);
        var r = document.getElementById('bh-raw');
        if (r && r.parentNode) r.parentNode.removeChild(r);
        bind(root);
        refreshClaimState(root);
    }

    var API = {
        VERSION: '1.0.0',
        WAX: WAX, TIER_RANK: TIER_RANK, TASK_CAP: TASK_CAP,
        esc: esc, splitCells: splitCells, parsePayload: parsePayload,
        findSection: findSection, collectCards: collectCards, isLocked: isLocked,
        taskKey: taskKey, buildTask: buildTask, renderFromRaw: renderFromRaw,
        claim: claim, raw: ''
    };
    window.__BH__ = API;

    if (document.readyState === 'complete' || document.readyState === 'interactive') setTimeout(boot, 40);
    else document.addEventListener('DOMContentLoaded', function () { setTimeout(boot, 40); });
})();

</script>
</body>
