<style>
:root{color-scheme:dark;--ink:#efe4ce;--muted:#b5aa98;--line:#75654d;--panel:#16191b;--panel2:#202426;--bronze:#c4914c;--bronze2:#7f542a;--danger:#d17864;--ok:#78ad86;--shadow:rgba(0,0,0,.42)}
