    <script>
        $(function () {
            var $root = $('body');
            var raw = $root.find('.fif-domain-raw').text() || '';

            /* ---------- Phân tích ---------- */
            function lines() {
                var out = [];
                var re = /\[([^\]]*)\]/g;
                var m;
                while ((m = re.exec(raw)) !== null) {
                    var parts = m[1].split('|');
                    for (var i = 0; i < parts.length; i++) parts[i] = String(parts[i] === undefined ? '' : parts[i]).trim();
                    if (parts.length >= 2 && parts[0]) out.push(parts);
                }
                return out;
            }

            function esc(s) {
                return String(s === undefined || s === null ? '' : s)
                    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
            }

            var L = lines();
            if (!L.length) {
                $root.find('#fif-empty').text('Chưa lấy được dữ liệu lãnh địa').show();
                return;
            }

            /* ---------- Lấy trường dữ liệu ---------- */
            function first(key) {
                for (var i = 0; i < L.length; i++) if (L[i][0] === key) return L[i];
                return null;
            }
            function all(key) {
                var out = [];
                for (var i = 0; i < L.length; i++) if (L[i][0] === key) out.push(L[i]);
                return out;
            }

            var head = first('领地') || [];
            var reign = first('治下') || [];
            var core = first('核心') || [];
            var mouth = first('人口') || [];
            var vault = first('金库') || [];
            var income = first('收益') || [];
            var armies = all('军事');
            var subs = all('分区');
            var marks = all('地标');
            var goods = all('资源点');
            var neighbor = first('邻邦') || [];

            /* ---------- Tiêu đề đầu trang ---------- */
            var name = head[1] || 'Vùng Đất Vô Danh';
            $root.find('#fif-name').text(name);
            $root.find('#fif-seal').text(String(name).slice(0, 2));

            var chips = [];
            function chip(text, cls) {
                if (!text) return;
                chips.push('<span class="fif-chip ' + (cls || '') + '">' + esc(text) + '</span>');
            }
            chip(head[2], 'fif-chip-tier');
            chip(head[3]);
            chip(head[4]);
            var st = head[5] || '';
            /* Trạng thái lãnh địa có năm mức: Chưa khai phá/Đang mở mang/Thanh bình/Bất ổn/Bị vây hãm.
               Hai mức đầu là trạng thái trung tính "đang xây dựng", Thanh bình là tốt, Bất ổn/Bị vây hãm là trạng thái cảnh báo. */
            var stOk = /承平|拓置中/.test(st);
            chip(st, stOk ? 'fif-chip-state is-ok' : 'fif-chip-state');
            $root.find('#fif-subline').html(chips.join(''));

            /* ---------- 4 ô chỉ số ---------- */
            function statCell(k, v, kind) {
                var cls = 'fif-stat-v';
                if (kind === 'num') {
                    var n = parseFloat(String(v).replace(/[^0-9.\-]/g, ''));
                    if (!isNaN(n)) { if (n < 35) cls += ' is-low'; else if (n >= 75) cls += ' is-high'; }
                } else {
                    cls += ' is-text';
                }
                return '<div class="fif-stat"><div class="fif-stat-k">' + esc(k) + '</div>'
                    + '<div class="' + cls + '">' + esc(v || '—') + '</div></div>';
            }
            var stats = '';
            stats += statCell('Trị An', core[1], 'num');
            stats += statCell('Lòng Dân', core[2], 'num');
            stats += statCell('Thương Lộ', core[3], 'text');
            stats += statCell('Kho Tàng', core[4], 'num');
            $root.find('#fif-stats').html(stats);

            /* ---------- Dòng mục ---------- */
            function row(key, val) {
                if (!val) return '';
                return '<div class="fif-row"><div class="fif-key">' + esc(key) + '</div>'
                    + '<div class="fif-val">' + esc(val) + '</div></div>';
            }
            /* AI đôi khi sẽ viết nhãn vào giá trị (dạng như "Tổng quản Haldi"), ở đây sẽ lược bỏ để tránh hiển thị thành "Tổng quản Tổng quản Haldi" */
            function stripLabel(v, label) {
                var s = String(v === undefined || v === null ? '' : v).trim();
                if (!s) return '';
                if (s.indexOf(label) === 0) s = s.slice(label.length).replace(/^[\s:：·]+/, '');
                return s;
            }
            function rowJoin(key, arr) {
                var bits = [];
                for (var i = 0; i < arr.length; i++) if (arr[i]) bits.push(esc(arr[i]));
                if (!bits.length) return '';
                return '<div class="fif-row"><div class="fif-key">' + esc(key) + '</div>'
                    + '<div class="fif-val">' + bits.join('<span class="fif-sep">◆</span>') + '</div></div>';
            }

            var rows = '';
            rows += rowJoin('Cai quản', [
                reign[1],
                reign[2] ? 'Lãnh chúa ' + stripLabel(reign[2], 'Lãnh chúa') : '',
                reign[3] ? 'Tổng quản ' + stripLabel(reign[3], 'Tổng quản') : '',
                reign[4]
            ]);
            rows += row('Dân số', mouth[1]);
            if (vault[1]) rows += row('Kho bạc', vault[1] + ' ' + (vault[2] || ''));
            if (income[2]) rows += row('Thu nhập', (income[1] ? income[1] + ' ' : '') + income[2] + ' ' + (income[3] || ''));
            var builds = all('建造');
            if (builds.length) {
                var bd = [];
                for (var b = 0; b < builds.length; b++) bd.push(builds[b][1] + (builds[b][2] ? ' ×' + builds[b][2] : ''));
                rows += row('Kiến thiết', bd.join('、'));
            }
            rows += row('Láng giềng', neighbor[1]);
            $root.find('#fif-rows').html(rows);

            /* ---------- Nhóm thẻ ---------- */
            function tiles($box, $group, arr, withMark) {
                if (!arr.length) { $group.hide(); return; }
                var html = '';
                for (var i = 0; i < arr.length; i++) {
                    var a = arr[i];
                    var text = a[1] || '';
                    if (a[2]) text += '　' + a[2] + (a[3] ? ' · ' + a[3] : '');
                    html += '<span class="fif-tile">' + (withMark ? '<span class="fif-tile-mark">⚔</span>' : '') + esc(text) + '</span>';
                }
                $box.html(html);
                $group.show();
            }
            tiles($root.find('#fif-army'), $root.find('#fif-army-group'), armies, true);
            tiles($root.find('#fif-subs'), $root.find('#fif-sub-group'), subs, false);

            /* ---------- Thắng cảnh và điểm tài nguyên (dùng chung một nhóm thẻ) ---------- */
            (function () {
                var box = [];
                for (var i = 0; i < marks.length; i++) {
                    if (marks[i][1]) box.push({ t: marks[i][1], k: '景' });
                }
                for (var j = 0; j < goods.length; j++) {
                    var g = goods[j];
                    if (!g[1]) continue;
                    /* [Điểm tài nguyên|Tên điểm tài nguyên|Số lượng phần|Chu kỳ|Trạng thái] —— Khi số lượng là "chưa rõ" thì không hiển thị sản lượng */
                    var amt = String(g[2] === undefined ? '' : g[2]).trim();
                    var cyc = String(g[3] === undefined ? '' : g[3]).trim();
                    var st = String(g[4] === undefined ? '' : g[4]).trim();
                    var sub = '';
                    if (amt && amt !== '未知' && !/^[?？—-]+$/.test(amt)) {
                        sub = amt + (/份$/.test(amt) ? '' : '份') + (cyc ? '/' + cyc : '');
                    }
                    if (st) sub += (sub ? ' · ' : '') + st;
                    box.push({ t: g[1] + (sub ? '　' + sub : ''), k: '产' });
                }
                if (!box.length) { $root.find('#fif-mark-group').hide(); return; }
                var html = '';
                for (var k2 = 0; k2 < box.length; k2++) {
                    html += '<span class="fif-tile"><span class="fif-tile-mark">' + box[k2].k + '</span>'
                        + esc(box[k2].t) + '</span>';
                }
                $root.find('#fif-marks').html(html);
                $root.find('#fif-mark-group').show();
            })();

            if (!rows && !armies.length && !subs.length && !marks.length && !goods.length) {
                $root.find('#fif-empty').text('Chưa lấy được dữ liệu lãnh địa').show();
            }

            /* ---------- Điền lại vào ô nhập ---------- */
            function fillInput(text) {
                try {
                    var textarea = window.parent.document.querySelector('#send_textarea');
                    if (textarea) {
                        var old = textarea.value.trim();
                        textarea.value = old ? old + "\n" + text : text;
                        textarea.dispatchEvent(new Event('input', { bubbles: true }));
                        return true;
                    }
                } catch (e) { }
                return false;
            }

            $root.find('#fif-ask').on('click', function () {
                var ok = fillInput('【Tra cứu lãnh vụ】' + name);
                if (ok) $(this).text('Đã lưu vào bản nháp').css('opacity', '0.6');
            });

            $root.find('#fif-refresh').on('click', function () {
                fillInput('【Khảo sát lãnh địa】' + name);
            });
        });
    </script>
