            var CATS = [['all', 'Tất cả'], ['防务', 'Phòng ngự'], ['经济', 'Kinh tế'], ['民生', 'Dân sinh'], ['军事', 'Quân sự']];
            var QUALS = [['all', 'Tất cả'], ['普通', 'Phổ thông'], ['优良', 'Ưu tú'], ['稀有', 'Hiếm'], ['史诗', 'Sử thi'], ['传说', 'Truyền thuyết'], ['神话', 'Thần thoại']];

