                    if (p[0] !== 'Xây dựng') continue;
                    if (p.length < 8) continue;
                    var rec = {
                        idx: out.length,
                        code: field(p, 1),
                        cat: field(p, 2),
                        name: field(p, 3),
                        qual: field(p, 4),
                        cost: field(p, 5),
                        time: field(p, 6),
                        effect: field(p, 7),
                        pre: field(p, 8)
                    };
                    if (!rec.cat || ['Phòng thủ', 'Kinh tế', 'Dân sinh', 'Quân sự'].indexOf(rec.cat) < 0) rec.cat = 'Kinh tế';
