                        +   (r.time ? '<div class="fib-row"><span class="fib-rk">Thời hạn</span><span class="fib-rv fib-time">' + esc(r.time) + '</span></div>' : '')
                        +   (r.effect ? '<div class="fib-row"><span class="fib-rk">Hiệu quả</span><span class="fib-rv">' + esc(r.effect) + '</span></div>' : '')
