                    $go.prop('disabled', true).removeClass('fib-ready').text('Đã lưu vào bản nháp');
                } else if (n === 0) {
                    $go.prop('disabled', true).removeClass('fib-ready').text('Khởi công');
                } else {
                    $go.prop('disabled', false).addClass('fib-ready').text('Khởi công (' + n + ')');
                }
                if (submitted) {
                    $selinfo.text('Đã lưu ' + n + ' công trình vào bản nháp').addClass('fib-has');
                } else if (n === 0) {
                    $selinfo.text('Chưa chọn hạng mục · Nhấp thẻ để chọn nhiều').removeClass('fib-has');
                } else {
                    $selinfo.text('Đã chọn ' + n + ' công trình').addClass('fib-has');
                }
                if ($all.length) $all.text(allVisiblePicked() ? 'Bỏ chọn tất cả' : 'Chọn tất cả đang hiện');
