                        var old = textarea.value.trim();
                        textarea.value = old ? old + "\n" + text : text;
                        textarea.dispatchEvent(new Event('input', { bubbles: true }));
                        return true;
                    }
                } catch (e) { }
                return false;
            }

            function buildLine(r) {
                return '【Khởi công】' + (r.code ? r.code + ' ' : '') + r.name
                    + ' ｜ ' + r.cat + ' · ' + (r.qual || 'Phổ thông')
                    + ' ｜ Dự toán ' + (r.cost || 'Quyết toán theo thực tế')
                    + ' ｜ Thời hạn ' + (r.time || 'Chưa xác định')
                    + ' ｜ ' + (r.effect || '');
            }

            /* ---------- Sự kiện ---------- */
            $list.on('click', '.fib-card', function () {
                var $card = $(this);
                var idx = parseInt($card.attr('data-idx'), 10);
                if (isNaN(idx)) return;
                if (picked[idx]) { delete picked[idx]; $card.removeClass('fib-picked'); }
                else { picked[idx] = true; $card.addClass('fib-picked'); }
                submitted = false;
                syncGo();
            });

            $all.on('click', function () {
                var v = visibleIdx();
                if (allVisiblePicked()) {
                    for (var i = 0; i < v.length; i++) delete picked[v[i]];
                    $list.children('.fib-card').each(function () {
                        var $c = $(this);
                        var j = parseInt($c.attr('data-idx'), 10);
                        if (v.indexOf(j) >= 0) $c.removeClass('fib-picked');
                    });
                } else {
                    for (var k = 0; k < v.length; k++) picked[v[k]] = true;
                    $list.children('.fib-card').each(function () {
                        var $c = $(this);
                        var j = parseInt($c.attr('data-idx'), 10);
                        if (v.indexOf(j) >= 0) $c.addClass('fib-picked');
                    });
                }
