                    + '<div class="fir-cell-v ' + (cls || '') + '">' + esc(v || '—') + '</div></div>';
            }
            var estText = est[1] ? (group(num(est[1])) || est[1]) + ' ' + (est[2] || '') : '—';
            top += cell('Định giá lãnh địa', estText);
            var netN = net.length ? num(net[1]) : null;
            top += cell('Số ngạch ròng kỳ này', net[1] ? (group(netN) || net[1]) + ' ' + (net[2] || '') : '—',
                netN === null ? '' : (netN >= 0 ? 'fir-pos' : 'fir-neg'));
            var vaultText = vault[1] ? ((num(vault[1]) !== null ? group(num(vault[1])) : vault[1]) + ' ' + (vault[2] || '')) : '—';
            top += cell('Tồn dư phủ khố', vaultText, (num(vault[1]) !== null && num(vault[1]) < 0) ? 'fir-neg' : '');
            $root.find('#fir-top').html(top);

            /* ---------- Hai cột thu chi ---------- */
            function sumOf(arr) {
                var s = 0, has = false;
                for (var i = 0; i < arr.length; i++) {
                    var n = num(arr[i][2]);
                    if (n !== null) { s += n; has = true; }
                }
                return has ? s : null;
            }
            function colList($box, arr) {
                if (!arr.length) {
                    $box.html('<div class="fir-col-empty">Không có</div>');
                    return;
                }
                var html = '';
                for (var i = 0; i < arr.length; i++) {
                    var n = num(arr[i][2]);
                    html += '<div class="fir-li"><span class="fir-li-n">' + esc(arr[i][1] || 'Chưa đặt tên') + '</span>'
                        + '<span class="fir-li-v">' + esc(n === null ? (arr[i][2] || '') : group(n)) + '</span></div>';
                }
                $box.html(html);
            }
            colList($root.find('#fir-in-list'), incomes);
            colList($root.find('#fir-out-list'), outs);
            var inSum = sumOf(incomes), outSum = sumOf(outs);
            var unit = (incomes[0] && incomes[0][3]) || (outs[0] && outs[0][3]) || '';
            $root.find('#fir-in-sum').text(inSum === null ? '—' : '+' + group(inSum) + (unit ? ' ' + unit : ''));
            $root.find('#fir-out-sum').text(outSum === null ? '—' : '-' + group(outSum) + (unit ? ' ' + unit : ''));

            /* ---------- Số dư ròng ---------- */
            var finalNet = netN;
            if (finalNet === null && inSum !== null) finalNet = inSum - (outSum || 0);
            var $netV = $root.find('#fir-net-v');
            if (finalNet === null) {
                $netV.text('—');
            } else {
                $netV.text((finalNet >= 0 ? '+' : '') + group(finalNet) + (unit ? ' ' + unit : ''))
                    .addClass(finalNet >= 0 ? 'fir-pos' : 'fir-neg');
                $root.find('#fir-net-k').text(finalNet >= 0 ? 'Kết dư kỳ này' : 'Thâm hụt kỳ này');
            }

            /* ---------- Biến động trị lý ---------- */
            if (metrics.length) {
                var mh = '';
                for (var i = 0; i < metrics.length; i++) {
                    var v = String(metrics[i][2] || '');
                    var cls = /^[+]/.test(v) ? 'fir-chip-up' : (/^[-]/.test(v) ? 'fir-chip-down' : '');
                    mh += '<span class="fir-chip ' + cls + '">'
                        + '<span class="fir-chip-k">' + esc((metrics[i][1] || '') + v) + '</span>'
                        + (metrics[i][3] ? '<span class="fir-chip-r">' + esc(metrics[i][3]) + '</span>' : '')
                        + '</span>';
                }
                $root.find('#fir-metrics').html(mh);
                $root.find('#fir-metric-sec').show();
            }

            /* ---------- Sự kiện ---------- */
            if (events.length) {
                var eh = '';
                for (var e = 0; e < events.length; e++) {
                    eh += '<div class="fir-ev"><span class="fir-ev-i">◆</span><span>' + esc(events[e][1]) + '</span></div>';
                }
                $root.find('#fir-events').html(eh);
                $root.find('#fir-event-sec').show();
            }

            /* ---------- Phán quyết ---------- */
            if (order && order[1]) {
                $root.find('#fir-order').html('<b>Phán quyết kỳ này:</b>' + esc(order[1])).show();
            }

            if (!incomes.length && !outs.length && !metrics.length && !events.length) {
                $root.find('#fir-empty').text('Chưa lấy được dữ liệu kết toán').show();
            }

            /* ---------- Điền vào khung nhập ---------- */
            function fillInput(text) {
                try {
                    var textarea = window.parent.document.querySelector('#send_textarea');
                    if (textarea) {
                        var old = textarea.value.trim();
                        textarea.value = old ? old + "\n" + text : text;
                        textarea.dispatchEvent(new Event('input', { bubbles: true }));
                        return true;
                    }
                } catch (e2) { }
                return false;
            }

            $root.find('#fir-ok').on('click', function () {
                if (fillInput('【Ký duyệt kết toán tháng】' + (head[1] || '') + ' ' + (head[3] || ''))) {
                    $(this).text('Đã lưu vào bản nháp').css('opacity', '0.6');
                }
            });

            $root.find('#fir-again').on('click', function () {
                fillInput('【Tra cứu sổ sách kỳ trước】' + (head[1] || ''));
            });
        });
    </script>
</body>
</html>
